1	// Package log implements an append-only, batch-commit segmented log.
2	//
3	// A writer stages a batch of opaque records with Append and publishes it
4	// atomically with Commit, or publishes several staged batches atomically
5	// with CommitGroup. AppendIdempotent stages a batch under a caller key:
6	// repeating a key with byte-identical records returns the first batch
7	// and its sequence across retries and restarts, while different records
8	// conflict. Readers only ever see committed batches, in strictly
9	// increasing sequence order starting at 1. Reads locate each batch
10	// through a persistent segment-level index in a sidecar file
11	// ("index.idx"): Open adopts it incrementally, and when it is missing,
12	// truncated, version-mismatched, checksum-bad or contradictory to the
13	// segments, Open rebuilds it from the segment files, so losing the
14	// index never loses data — idempotency keys live in the segments, not
15	// in the sidecar, and are recovered on every open path.
16	package log
17	
18	import (
19		"bytes"
20		"encoding/binary"
21		"errors"
22		"fmt"
23		"hash/crc32"
24		"os"
25		"path/filepath"
26		"sort"
27		"strconv"
28		"strings"
29		"sync"
30		"unicode/utf8"
31	)
32	
33	var (
34		// ErrNotCommitted is returned when reading a sequence that has been
35		// staged with Append but not yet committed.
36		ErrNotCommitted = errors.New("log: batch not committed")
37		// ErrUnknownBatch is returned for sequence 0, sequences that were
38		// never reserved, sequences beyond the reserved range, and batches
39		// that have already been committed.
40		ErrUnknownBatch = errors.New("log: unknown batch")
41		// ErrCorruptSegment is returned when a segment file fails validation
42		// while opening or scanning the log.
43		ErrCorruptSegment = errors.New("log: corrupt segment")
44		// ErrInvalidOptions is returned by Open when the options are not
45		// usable, e.g. a non-positive segment capacity.
46		ErrInvalidOptions = errors.New("log: invalid options")
47		// ErrSyncFailed is returned by Commit and CommitGroup when
48		// Options.Sync is set and fsyncing the segment file fails. The
49		// batches stay staged and keep their reserved sequences; committing
50		// them again retries.
51		ErrSyncFailed = errors.New("log: sync failed")
52		// ErrInvalidBatchID is returned by AppendIdempotent for an empty
53		// key, a key containing a NUL byte, a key that is not valid UTF-8 or
54		// a key longer than 256 bytes.
55		ErrInvalidBatchID = errors.New("log: invalid batch id")
56		// ErrBatchIDConflict is returned by AppendIdempotent when a key was
57		// used before but the new records differ from the first call's in
58		// length, order or bytes.
59		ErrBatchIDConflict = errors.New("log: batch id conflict")
60	)
61	
62	var errClosed = errors.New("log: closed")
63	
64	// syncFile fsyncs a segment file. It is a variable so tests can
65	// simulate sync failures.
66	var syncFile = func(f *os.File) error { return f.Sync() }
67	
68	// Options configures a Log opened with Open.
69	type Options struct {
70		// SegmentBytes is the capacity of one segment file in bytes. Once a
71		// non-empty segment would exceed it, the log rolls to a new segment.
72		// A single batch or group larger than the capacity occupies its own
73		// segment. Must be positive.
74		SegmentBytes int
75		// Sync makes Commit and CommitGroup fsync the segment file before
76		// returning, so a returned commit is durable.
77		Sync bool
78	}
79	
80	// Batch is a group of records identified by a single sequence number.
81	// A Batch returned by Append is staged; after Commit or CommitGroup it
82	// is readable. A batch staged with AppendIdempotent additionally
83	// carries the caller-chosen idempotency key, returned by ID; anonymous
84	// batches return "" from ID.
85	type Batch struct {
86		seq     uint64
87		id      string
88		records [][]byte
89		owner   *Log
90	}
91	
92	// Seq returns the sequence number reserved for the batch.
93	func (b Batch) Seq() uint64 { return b.seq }
94	
95	// ID returns the batch's idempotency key as given to
96	// AppendIdempotent, or "" for an anonymous batch staged with Append.
97	func (b Batch) ID() string { return b.id }
98	
99	// Records returns a copy of the batch's records.
100	func (b Batch) Records() [][]byte { return copyRecords(b.records) }
101	
102	// Segment describes one segment file by the committed sequences it holds.
103	type Segment struct {
104		FirstSeq uint64
105		LastSeq  uint64
106	}
107	
108	// entryRef locates one committed batch body inside a segment file. The
109	// persistent index sidecar stores the same locations; its loss or
110	// invalidation is always safe because Open rebuilds it from the
111	// segments. gen is the publication generation of the commit that
112	// published the batch; every member of a group commit shares one gen,
113	// which lets a streaming replay snapshot see the whole group or none of
114	// it.
115	type entryRef struct {
116		seg    int // segment file number
117		off    int // offset of the batch body within the segment
118		length int // length of the batch body
119		gen    uint64
120		id     string // idempotency key, "" for an anonymous batch
121		keyed  bool   // body uses key framing (BCLI, or any BCLK member)
122	}
123	
124	// Log is an append-only batch-commit log stored in a directory of
125	// segment files. It is safe for concurrent use, but the writer side is
126	// expected to be a single goroutine (see README Limits).
127	//
128	// The read and write paths are decoupled: writers take mu exclusively,
129	// while readers hold it only for the brief index and staged-state
130	// lookups. Segment file reads, decoding and user callbacks happen
131	// outside the lock, so a slow reader or a long replay never blocks a
132	// committing writer.
133	type Log struct {
134		dir  string
135		opts Options
136	
137		// mu guards the mutable index and write state below. Readers never
138		// hold it across file I/O, decoding or callbacks.
139		mu         sync.RWMutex
140		file       *os.File // current segment, nil until first write
141		fileSize   int
142		idxFile    *os.File // index sidecar, opened for append
143		idxSize    int
144		segIndex   int // index of the current segment file, 0 = none yet
145		curBatches int // committed batches in the current segment
146		nextSeq    uint64
147		staged     map[uint64][][]byte
148		stagedID   map[uint64]string // idempotency key of staged keyed batches
149		ids        map[string]uint64 // key -> seq of staged or committed keyed batch
150		index      map[uint64]entryRef
151		segs       []Segment // segments holding at least one committed batch
152		gen        uint64    // publication generation of the last commit
153		closed     bool
154	}
155	
156	// Open opens the log in dir, creating the directory if needed. The
157	// committed set is taken from the persistent index sidecar when it can
158	// be adopted incrementally; if the sidecar is missing, truncated, from
159	// another version, checksum-bad or contradictory to the segment files,
160	// Open transparently rebuilds it by scanning the segments once. Either
161	// path yields identical reads, replays, segment listings and errors.
162	//
163	// A half-written tail of the last segment — the remnant of a crash
164	// mid-write — is replaced by a durable hole marker without error and
165	// its reserved sequences stay permanent holes across reopens; any other
166	// inconsistency is ErrCorruptSegment.
167	func Open(dir string, opts Options) (*Log, error) {
168		if opts.SegmentBytes <= 0 {
169			return nil, ErrInvalidOptions
170		}
171		if err := os.MkdirAll(dir, 0o755); err != nil {
172			return nil, err
173		}
174		entries, err := os.ReadDir(dir)
175		if err != nil {
176			return nil, err
177		}
178		var indices []int
179		for _, e := range entries {
180			if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
181				continue
182			}
183			n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
184			if err != nil {
185				continue
186			}
187			indices = append(indices, n)
188		}
189		sort.Ints(indices)
190	
191		l := &Log{
192			dir:      dir,
193			opts:     opts,
194			nextSeq:  1,
195			staged:   make(map[uint64][][]byte),
196			stagedID: make(map[uint64]string),
197			ids:      make(map[string]uint64),
198			index:    make(map[uint64]entryRef),
199		}
200	
201		// Segment sizes are all the segment metadata adoption needs; the
202		// contents are touched only by the cheap CRC pass, never decoded
203		// entry by entry.
204		sizes := make(map[int]int, len(indices))
205		for _, n := range indices {
206			st, err := os.Stat(l.segmentPath(n))
207			if err != nil {
208				return nil, err
209			}
210			sizes[n] = int(st.Size())
211		}
212	
213		snapshot, ok := l.adoptIndex(indices, sizes)
214		if !ok {
215			snapshot, err = l.rebuildFromSegments(indices)
216			if err != nil {
217				return nil, err
218			}
219		}
220		sortIndexSnapshot(&snapshot)
221		if err := l.installSnapshot(snapshot, indices); err != nil {
222			return nil, err
223		}
224	
225		if len(indices) > 0 {
226			l.segIndex = indices[len(indices)-1]
227			if err := l.openCurrent(); err != nil {
228				return nil, err
229			}
230		}
231		if err := l.openIndex(); err != nil {
232			return nil, err
233		}
234		return l, nil
235	}
236	
237	// installSnapshot populates the in-memory index, segment listing, staged
238	// holes, key map and next-sequence counter from an adopted or rebuilt
239	// snapshot. Both open paths funnel through here so their observable
240	// state is identical. Entries must be ordered by (segment, disk offset);
241	// each entry (a single commit or one group) gets one publication
242	// generation. A key claimed by two complete entries, or a complete
243	// entry whose member framing disagrees with the index, is corruption.
244	func (l *Log) installSnapshot(p parsedIndex, indices []int) error {
245		for i := range p.entries {
246			e := &p.entries[i]
247			l.gen++
248			for _, m := range e.members {
249				l.index[m.seq] = entryRef{
250					seg: e.seg, off: m.off, length: m.length, gen: l.gen,
251					id: m.id, keyed: e.keyed,
252				}
253				if m.id != "" {
254					if _, dup := l.ids[m.id]; dup {
255						return ErrCorruptSegment
256					}
257					l.ids[m.id] = m.seq
258				}
259				if m.seq >= l.nextSeq {
260					l.nextSeq = m.seq + 1
261				}
262			}
263		}
264		// Segment listing: one entry per physical segment that holds at
265		// least one committed batch.
266		segSeen := make(map[int]int)
267		for i := range p.entries {
268			e := &p.entries[i]
269			var first, last uint64
270			for j, m := range e.members {
271				if j == 0 {
272					first, last = m.seq, m.seq
273				}
274				if m.seq < first {
275					first = m.seq
276				}
277				if m.seq > last {
278					last = m.seq
279				}
280			}
281			if idx, known := segSeen[e.seg]; known {
282				if first < l.segs[idx].FirstSeq {
283					l.segs[idx].FirstSeq = first
284				}
285				if last > l.segs[idx].LastSeq {
286					l.segs[idx].LastSeq = last
287				}
288			} else {
289				segSeen[e.seg] = len(l.segs)
290				l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
291			}
292		}
293		// Holes reserve sequences permanently: they read as staged (never
294		// committed) and are never reused, across any number of reopens.
295		for i := range p.holes {
296			for _, seq := range p.holes[i].seqs {
297				if seq == 0 {
298					continue
299				}
300				if _, committed := l.index[seq]; !committed {
301					l.staged[seq] = nil
302				}
303				if seq >= l.nextSeq {
304					l.nextSeq = seq + 1
305				}
306			}
307		}
308		if len(indices) > 0 {
309			last := indices[len(indices)-1]
310			l.curBatches = 0
311			for i := range p.entries {
312				if p.entries[i].seg == last {
313					l.curBatches += len(p.entries[i].members)
314				}
315			}
316		}
317		return nil
318	}
319	
320	// sortIndexSnapshot orders a snapshot's records by (segment, offset),
321	// the canonical on-disk and publication order.
322	func sortIndexSnapshot(p *parsedIndex) {
323		sort.SliceStable(p.entries, func(i, j int) bool {
324			if p.entries[i].seg != p.entries[j].seg {
325				return p.entries[i].seg < p.entries[j].seg
326			}
327			return p.entries[i].off < p.entries[j].off
328		})
329		sort.SliceStable(p.holes, func(i, j int) bool {
330			if p.holes[i].seg != p.holes[j].seg {
331				return p.holes[i].seg < p.holes[j].seg
332			}
333			return p.holes[i].off < p.holes[j].off
334		})
335	}
336	
337	// adoptIndex is the incremental open path. It verifies the sidecar
338	// against the segment files without decoding record bodies: its records
339	// must tile a prefix of the segment files from offset zero, every
340	// on-disk CRC must match, and member locations must agree with the entry
341	// headers. Any framing defect, a truncated final record, a version
342	// mismatch or a contradiction makes it return ok=false and Open rebuilds
343	// from the segments instead.
344	//
345	// The segments may legitimately extend past a verified index — the
346	// crash window between the segment sync and the index record sync. That
347	// suffix (extra bytes of the last covered segment, plus any whole later
348	// segment) is parsed incrementally: complete entries get indexed, a
349	// torn tail of the last segment becomes a hole marker, so adoption
350	// still costs one small decode rather than a full scan.
351	func (l *Log) adoptIndex(indices []int, sizes map[int]int) (parsedIndex, bool) {
352		if len(indices) == 0 {
353			// No segments: nothing to index; openIndex creates the sidecar
354			// lazily with its header when the first commit lands.
355			return parsedIndex{}, true
356		}
357		data, err := l.readIndexBytes()
358		if err != nil {
359			return parsedIndex{}, false
360		}
361		p, tailLen, err := readIndexFile(data)
362		if err != nil || tailLen > 0 {
363			// Missing/truncated/foreign sidecar: the rebuild path owns
364			// these cases.
365			return parsedIndex{}, false
366		}
367		if len(p.entries) == 0 && len(p.holes) == 0 {
368			// A recordless sidecar is valid only when every segment is
369			// empty; otherwise the sidecar is simply behind and the
370			// rebuild path catches up.
371			for _, n := range indices {
372				if sizes[n] != 0 {
373					return parsedIndex{}, false
374				}
375			}
376			return p, true
377		}
378		covered, covEnd, ok := l.verifySidecar(p, indices, sizes)
379		if !ok {
380			return parsedIndex{}, false
381		}
382	
383		// Everything at or after covered is unverified suffix: the unindexed
384		// tail bytes of segment covered, then every whole later segment.
385		pos := 0
386		for pos < len(indices) && indices[pos] < covered {
387			pos++
388		}
389		var extra []diskRecord
390		for si := pos; si < len(indices); si++ {
391			n := indices[si]
392			raw, err := os.ReadFile(l.segmentPath(n))
393			if err != nil {
394				return parsedIndex{}, false
395			}
396			base := 0
397			if n == covered {
398				if covEnd > len(raw) {
399					return parsedIndex{}, false
400				}
401				base = covEnd
402			}
403			batches, markers, tail, perr := parseSegment(raw[base:])
404			if perr != nil {
405				// Tampering in the suffix surfaces through the rebuild path
406				// with the identical ErrCorruptSegment.
407				return parsedIndex{}, false
408			}
409			if tail != nil && si != len(indices)-1 {
410				return parsedIndex{}, false
411			}
412			for k := 0; k < len(batches); {
413				diskOff := batches[k].diskOff + base
414				j := k + 1
415				for j < len(batches) && batches[j].diskOff+base == diskOff {
416					j++
417				}
418				e := indexEntry{
419					seg:     n,
420					off:     diskOff,
421					length:  batches[k].diskLen,
422					diskCRC: batches[k].diskCRC,
423					keyed:   batches[k].keyed,
424					members: make([]indexMember, 0, j-k),
425				}
426				for _, pb := range batches[k:j] {
427					e.members = append(e.members, indexMember{
428						seq: pb.seq, id: pb.id, off: pb.off + base, length: pb.length,
429					})
430				}
431				p.entries = append(p.entries, e)
432				extra = append(extra, diskRecord{seg: n, off: diskOff, enc: encodeEntryRecord(e)})
433				k = j
434			}
435			for _, h := range markers {
436				ih := indexHole{
437					seg: n, off: h.off + base, length: h.length, diskCRC: h.crc,
438					seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
439				}
440				p.holes = append(p.holes, ih)
441				extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
442			}
443			if tail != nil {
444				keep := make([]uint64, 0, len(tail.seqs))
445				for _, seq := range tail.seqs {
446					if seq > 0 {
447						keep = append(keep, seq)
448					}
449				}
450				if err := l.rewriteTail(n, base+tail.off, keep); err != nil {
451					return parsedIndex{}, false
452				}
453				if len(keep) > 0 {
454					marker := encodeHoles(keep)
455					crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
456					ih := indexHole{
457						seg: n, off: base + tail.off, length: len(marker), diskCRC: crc,
458						seqs: append(make([]uint64, 0, len(keep)), keep...),
459					}
460					p.holes = append(p.holes, ih)
461					extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
462				}
463			}
464		}
465	
466		// Persist the incrementally recovered records so later opens adopt
467		// them too. A crash during this append leaves a torn final index
468		// record, and the next open simply rebuilds.
469		if len(extra) > 0 {
470			if err := l.appendAdoptedSuffix(extra); err != nil {
471				return parsedIndex{}, false
472			}
473		}
474		return p, true
475	}
476	
477	// appendAdoptedSuffix appends incrementally recovered records to the
478	// sidecar and fsyncs it. Failure means the caller rebuilds instead.
479	func (l *Log) appendAdoptedSuffix(recs []diskRecord) error {
480		sort.SliceStable(recs, func(i, j int) bool {
481			if recs[i].seg != recs[j].seg {
482				return recs[i].seg < recs[j].seg
483			}
484			return recs[i].off < recs[j].off
485		})
486		f, err := os.OpenFile(l.indexPath(), os.O_WRONLY|os.O_APPEND, 0o644)
487		if err != nil {
488			return err
489		}
490		defer f.Close()
491		for _, r := range recs {
492			if _, err := f.Write(r.enc); err != nil {
493				return err
494			}
495		}
496		return f.Sync()
497	}
498	
499	// sidecarRec is one physical record the index claims.
500	type sidecarRec struct {
501		seg    int
502		off    int
503		length int
504		crc    uint32
505		entry  *indexEntry
506		hole   *indexHole
507	}
508	
509	// verifySidecar checks an already-framed parse against the physical
510	// segments without decoding any record body. It returns the last segment
511	// the index covers and the offset immediately after its records there.
512	//
513	// The covered segments must be a prefix of the segment files in the
514	// directory; within each one records must be strictly ordered, start at
515	// offset zero and tile without gaps or overlap. Every covered segment
516	// except the last must end exactly at the file size (nothing
517	// unindexed); the last one may stop short, leaving a suffix for
518	// incremental parsing. Every stored disk CRC is recomputed, and entry
519	// headers (magic and group membership layout) are checked.
520	func (l *Log) verifySidecar(p parsedIndex, indices []int, sizes map[int]int) (coveredSeg int, coveredEnd int, ok bool) {
521		if len(indices) == 0 {
522			return 0, 0, false
523		}
524		recs := make([]sidecarRec, 0, len(p.entries)+len(p.holes))
525		for i := range p.entries {
526			e := &p.entries[i]
527			recs = append(recs, sidecarRec{seg: e.seg, off: e.off, length: e.length, crc: e.diskCRC, entry: e})
528		}
529		for i := range p.holes {
530			h := &p.holes[i]
531			recs = append(recs, sidecarRec{seg: h.seg, off: h.off, length: h.length, crc: h.diskCRC, hole: h})
532		}
533		sort.SliceStable(recs, func(i, j int) bool {
534			if recs[i].seg != recs[j].seg {
535				return recs[i].seg < recs[j].seg
536			}
537			return recs[i].off < recs[j].off
538		})
539	
540		known := make(map[int]bool, len(indices))
541		for _, n := range indices {
542			known[n] = true
543		}
544		covered := false
545		seenSeq := make(map[uint64]bool)
546		seenKey := make(map[string]bool)
547		var f *os.File
548		openSeg := -1
549		closeFile := func() {
550			if f != nil {
551				f.Close()
552				f = nil
553				openSeg = -1
554			}
555		}
556		defer closeFile()
557	
558		prevSeg, prevEnd := -1, 0
559		for i := range recs {
560			r := &recs[i]
561			if !known[r.seg] || r.off < 0 || r.length < 16 {
562				return 0, 0, false
563			}
564			if r.seg != prevSeg {
565				// A new covered segment: the previous one must be tiled to
566				// its EOF, and the covered segments must be a prefix with no
567				// unindexed segment file in between.
568				if prevSeg != -1 && prevEnd != sizes[prevSeg] {
569					return 0, 0, false
570				}
571				if covered {
572					next := 0
573					found := false
574					for _, n := range indices {
575						if n > prevSeg {
576							next, found = n, true
577							break
578						}
579					}
580					if !found || r.seg != next || r.off != 0 {
581						return 0, 0, false
582					}
583				} else {
584					if r.seg != indices[0] || r.off != 0 {
585						return 0, 0, false
586					}
587				}
588				covered = true
589				prevSeg = r.seg
590				prevEnd = 0
591				closeFile()
592				var err error
593				f, err = os.Open(l.segmentPath(r.seg))
594				if err != nil {
595					return 0, 0, false
596				}
597				openSeg = r.seg
598			}
599			if openSeg != r.seg || r.off != prevEnd || r.off+r.length > sizes[r.seg] {
600				return 0, 0, false
601			}
602			if !l.verifyDiskRecord(f, r, seenSeq, seenKey) {
603				return 0, 0, false
604			}
605			prevEnd = r.off + r.length
606		}
607		lastSeg := recs[len(recs)-1].seg
608		lastEnd := prevEnd
609	
610		// Every segment file before the last covered one must carry at
611		// least one index record (no unindexed segment in the middle).
612		refSegs := map[int]bool{}
613		for i := range recs {
614			refSegs[recs[i].seg] = true
615		}
616		for _, n := range indices {
617			if n < lastSeg && !refSegs[n] {
618				return 0, 0, false
619			}
620		}
621		return lastSeg, lastEnd, true
622	}
