624	// verifyDiskRecord checks one index claim against the segment without
625	// holding the entry in memory: a small header read, a streaming CRC over
626	// a fixed-size scratch buffer, and small reads of group-member sequences
627	// and key frames. It never decodes record bodies.
628	func (l *Log) verifyDiskRecord(f *os.File, r *sidecarRec, seenSeq map[uint64]bool, seenKey map[string]bool) bool {
629		var hdr [16]byte
630		if _, err := f.ReadAt(hdr[:12], int64(r.off)); err != nil {
631			return false
632		}
633		// Stream the entry's CRC-covered prefix through one reused buffer,
634		// then compare against the stored trailing checksum.
635		h := crc32.NewIEEE()
636		buf := make([]byte, 64*1024)
637		remaining := r.length - 4
638		at := int64(r.off)
639		for remaining > 0 {
640			n := len(buf)
641			if n > remaining {
642				n = remaining
643			}
644			if _, err := f.ReadAt(buf[:n], at); err != nil {
645				return false
646			}
647			h.Write(buf[:n])
648			remaining -= n
649			at += int64(n)
650		}
651		var crcBytes [4]byte
652		if _, err := f.ReadAt(crcBytes[:], at); err != nil {
653			return false
654		}
655		stored := binary.LittleEndian.Uint32(crcBytes[:])
656		if h.Sum32() != stored || stored != r.crc {
657			return false
658		}
659	
660		switch {
661		case r.entry != nil:
662			e := r.entry
663			switch {
664			case bytes.Equal(hdr[:4], segmentMagic):
665				if e.keyed || len(e.members) != 1 || e.members[0].id != "" {
666					return false
667				}
668				return len(e.members) == 1 &&
669					e.members[0].seq == binary.LittleEndian.Uint64(hdr[4:12]) &&
670					e.members[0].off == r.off+4 &&
671					e.members[0].length == r.length-8 &&
672					markSeen(e.members, seenSeq, nil)
673			case bytes.Equal(hdr[:4], keyedMagic):
674				if !e.keyed || len(e.members) != 1 {
675					return false
676				}
677				m := e.members[0]
678				if m.id == "" ||
679					m.seq != binary.LittleEndian.Uint64(hdr[4:12]) ||
680					m.off != r.off+4 || m.length != r.length-8 {
681					return false
682				}
683				if _, ok := verifyKeyOnDisk(f, int64(m.off+8), m.id); !ok {
684					return false
685				}
686				return markSeen(e.members, seenSeq, seenKey)
687			case bytes.Equal(hdr[:4], groupMagic):
688				if e.keyed {
689					return false
690				}
691				if uint32(len(e.members)) != binary.LittleEndian.Uint32(hdr[4:8]) {
692					return false
693				}
694				if !checkMemberLayout(r, e) {
695					return false
696				}
697				for _, m := range e.members {
698					if m.id != "" {
699						return false
700					}
701					var seqBytes [8]byte
702					if _, err := f.ReadAt(seqBytes[:], int64(m.off)); err != nil {
703						return false
704					}
705					if m.seq != binary.LittleEndian.Uint64(seqBytes[:]) {
706						return false
707					}
708				}
709				return markSeen(e.members, seenSeq, nil)
710			case bytes.Equal(hdr[:4], keyedGroup):
711				if !e.keyed {
712					return false
713				}
714				if uint32(len(e.members)) != binary.LittleEndian.Uint32(hdr[4:8]) {
715					return false
716				}
717				if !checkMemberLayout(r, e) {
718					return false
719				}
720				for _, m := range e.members {
721					if _, ok := verifyKeyOnDisk(f, int64(m.off+8), m.id); !ok {
722						return false
723					}
724					var seqBytes [8]byte
725					if _, err := f.ReadAt(seqBytes[:], int64(m.off)); err != nil {
726						return false
727					}
728					if m.seq != binary.LittleEndian.Uint64(seqBytes[:]) {
729						return false
730					}
731				}
732				return markSeen(e.members, seenSeq, seenKey)
733			default:
734				return false
735			}
736		case r.hole != nil:
737			h2 := r.hole
738			if !bytes.Equal(hdr[:4], holeMagic) ||
739				uint32(len(h2.seqs)) != binary.LittleEndian.Uint32(hdr[4:8]) ||
740				r.length != 4+4+8*len(h2.seqs)+4 {
741				return false
742			}
743			// The reserved sequences themselves must agree with the marker,
744			// not just their count.
745			seqBytes := make([]byte, 8*len(h2.seqs))
746			if len(seqBytes) > 0 {
747				if _, err := f.ReadAt(seqBytes, int64(r.off+8)); err != nil {
748					return false
749				}
750				for i, seq := range h2.seqs {
751					if seq == 0 || seenSeq[seq] ||
752						seq != binary.LittleEndian.Uint64(seqBytes[8*i:8*i+8]) {
753						return false
754					}
755				}
756			}
757			return true
758		default:
759			return false
760		}
761	}
