763	// checkMemberLayout verifies that a group entry's member bodies tile the
764	// entry's CRC-covered payload with no gaps or overhang, starting right
765	// after the 8-byte group header.
766	func checkMemberLayout(r *sidecarRec, e *indexEntry) bool {
767		bodyStart := r.off + 8
768		for i, m := range e.members {
769			rel := m.off - r.off
770			if m.length <= 0 || rel < 8 || rel+m.length > r.length-4 {
771				return false
772			}
773			if i == 0 {
774				if m.off != bodyStart {
775					return false
776				}
777			} else {
778				prev := e.members[i-1]
779				if m.off != prev.off+prev.length {
780					return false
781				}
782			}
783		}
784		return e.members[len(e.members)-1].off+e.members[len(e.members)-1].length == r.off+r.length-4
785	}
786	
787	// verifyKeyOnDisk reads the 2-byte key length and key bytes at off and
788	// checks they name exactly want ("" requires a zero length). It returns
789	// the on-disk key length so callers can locate the seq that follows.
790	func verifyKeyOnDisk(f *os.File, off int64, want string) (int, bool) {
791		var lenBytes [2]byte
792		if _, err := f.ReadAt(lenBytes[:], off); err != nil {
793			return 0, false
794		}
795		klen := int(binary.LittleEndian.Uint16(lenBytes[:]))
796		if want == "" {
797			return 0, klen == 0
798		}
799		if klen != len(want) || klen > maxBatchIDLen {
800			return 0, false
801		}
802		raw := make([]byte, klen)
803		if _, err := f.ReadAt(raw, off+2); err != nil {
804			return 0, false
805		}
806		if string(raw) != want {
807			return 0, false
808		}
809		return klen, true
810	}
