812	// markSeen records every member sequence, rejecting 0 and duplicates;
813	// when seenKey is non-nil it does the same for member idempotency keys.
814	func markSeen(members []indexMember, seen map[uint64]bool, seenKey map[string]bool) bool {
815		for _, m := range members {
816			if m.seq == 0 || seen[m.seq] {
817				return false
818			}
819			seen[m.seq] = true
820			if seenKey != nil && m.id != "" {
821				if seenKey[m.id] {
822					return false
823				}
824				seenKey[m.id] = true
825			}
826		}
827		return true
828	}
