830	// rebuildFromSegments is the fallback open path: it decodes every
831	// segment exactly as a historical open did, recovers a torn tail of the
832	// last segment into a durable hole marker, and finally persists a fresh
833	// index snapshot. Tampering anywhere but the last segment's tail stays
834	// ErrCorruptSegment.
835	func (l *Log) rebuildFromSegments(indices []int) (parsedIndex, error) {
836		var p parsedIndex
837		for i, n := range indices {
838			data, err := os.ReadFile(l.segmentPath(n))
839			if err != nil {
840				return parsedIndex{}, err
841			}
842			batches, markers, tail, err := parseSegment(data)
843			if err != nil {
844				return parsedIndex{}, err
845			}
846			if tail != nil && i != len(indices)-1 {
847				// A half-written tail is a crash remnant only in the last
848				// segment; anywhere else it is tampering.
849				return parsedIndex{}, ErrCorruptSegment
850			}
851			for k := 0; k < len(batches); {
852				// Members of one group entry share diskOff; a single commit
853				// is an entry with one member.
854				diskOff := batches[k].diskOff
855				j := k + 1
856				for j < len(batches) && batches[j].diskOff == diskOff {
857					j++
858				}
859				e := indexEntry{
860					seg:     n,
861					off:     batches[k].diskOff,
862					length:  batches[k].diskLen,
863					diskCRC: batches[k].diskCRC,
864					keyed:   batches[k].keyed,
865					members: make([]indexMember, 0, j-k),
866				}
867				for _, pb := range batches[k:j] {
868					e.members = append(e.members, indexMember{seq: pb.seq, id: pb.id, off: pb.off, length: pb.length})
869				}
870				p.entries = append(p.entries, e)
871				k = j
872			}
873			for _, h := range markers {
874				p.holes = append(p.holes, indexHole{
875					seg: n, off: h.off, length: h.length, diskCRC: h.crc,
876					seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
877				})
878			}
879			if tail != nil {
880				// Replace the torn entry with a durable hole marker so its
881				// reserved sequences stay permanent holes, then index the
882				// replacement marker as part of the fresh snapshot.
883				keep := make([]uint64, 0, len(tail.seqs))
884				for _, seq := range tail.seqs {
885					if seq > 0 {
886						keep = append(keep, seq)
887					}
888				}
889				if err := l.rewriteTail(n, tail.off, keep); err != nil {
890					return parsedIndex{}, err
891				}
892				if len(keep) > 0 {
893					marker := encodeHoles(keep)
894					crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
895					p.holes = append(p.holes, indexHole{
896						seg: n, off: tail.off, length: len(marker), diskCRC: crc,
897						seqs: append(make([]uint64, 0, len(keep)), keep...),
898					})
899				}
900			}
901		}
902		sortIndexSnapshot(&p)
903		if err := l.writeIndexSnapshot(p); err != nil {
904			return parsedIndex{}, err
905		}
906		return p, nil
907	}
