909	// Append stages a batch of records and reserves the next sequence number
910	// for it. The batch becomes readable only after Commit or CommitGroup.
911	func (l *Log) Append(records [][]byte) (Batch, error) {
912		l.mu.Lock()
913		defer l.mu.Unlock()
914		if l.closed {
915			return Batch{}, errClosed
916		}
917		recs := copyRecords(records)
918		seq := l.nextSeq
919		l.nextSeq++
920		l.staged[seq] = recs
921		return Batch{seq: seq, records: recs, owner: l}, nil
922	}
923	
924	// AppendIdempotent stages a batch under a caller-chosen key that is
925	// unique within the log directory, and reserves the next sequence
926	// number for it, exactly as Append does for anonymous batches. Repeating
927	// a call with a key already in use is safe across network retries and
928	// process restarts:
929	//
930	//   - If records match the first call in length, order and every byte,
931	//     the first batch is returned with its original Seq — whether it is
932	//     still staged or already committed. No new sequence is reserved and
933	//     nothing is written again.
934	//   - If the records differ, ErrBatchIDConflict is returned.
935	//
936	// An empty key, a key containing a NUL byte, a key that is not valid
937	// UTF-8, or a key longer than 256 bytes returns ErrInvalidBatchID.
938	func (l *Log) AppendIdempotent(key string, records [][]byte) (Batch, error) {
939		l.mu.Lock()
940		defer l.mu.Unlock()
941		if l.closed {
942			return Batch{}, errClosed
943		}
944		if !validBatchID(key) {
945			return Batch{}, ErrInvalidBatchID
946		}
947		recs := copyRecords(records)
948		if seq, ok := l.ids[key]; ok {
949			// The first call is either still staged or already committed;
950			// compare against the exact bytes it owns so a retry cannot
951			// reserve another sequence or write a second entry.
952			var prior [][]byte
953			if staged, isStaged := l.staged[seq]; isStaged {
954				prior = staged
955			} else {
956				ref, known := l.index[seq]
957				if !known {
958					return Batch{}, ErrCorruptSegment
959				}
960				got, id, err := l.readRef(seq, ref)
961				if err != nil {
962					return Batch{}, err
963				}
964				if id != key {
965					return Batch{}, ErrCorruptSegment
966				}
967				prior = got
968			}
969			if !recordsEqual(prior, recs) {
970				return Batch{}, ErrBatchIDConflict
971			}
972			return Batch{seq: seq, id: key, records: copyRecords(prior), owner: l}, nil
973		}
974		seq := l.nextSeq
975		l.nextSeq++
976		l.staged[seq] = recs
977		l.stagedID[seq] = key
978		l.ids[key] = seq
979		return Batch{seq: seq, id: key, records: recs, owner: l}, nil
980	}
981	
982	// validBatchID reports whether key is an acceptable idempotency key:
983	// non-empty, valid UTF-8, NUL-free and at most 256 bytes long.
984	func validBatchID(key string) bool {
985		if key == "" || len(key) > maxBatchIDLen {
986			return false
987		}
988		if strings.IndexByte(key, 0) >= 0 {
989			return false
990		}
991		return utf8.ValidString(key)
992	}
993	
994	// recordsEqual reports whether two record slices agree in length, order
995	// and every byte.
996	func recordsEqual(a, b [][]byte) bool {
997		if len(a) != len(b) {
998			return false
999		}
1000		for i := range a {
1001			if !bytes.Equal(a[i], b[i]) {
1002				return false
1003			}
1004		}
1005		return true
1006	}
1007	
1008	// Commit makes a staged batch durable and readable, and returns its
1009	// reserved sequence number. Committing a batch that is not staged —
1010	// including one already committed — returns ErrUnknownBatch. With
1011	// Options.Sync a returned commit is durable: the segment entry and the
1012	// index sidecar record are both synced, one fsync each. If either
1013	// fsync fails Commit returns ErrSyncFailed, rolls both files back and
1014	// the batch stays staged, keeping its reserved sequence for a retry
1015	// that cannot produce a duplicate entry.
1016	func (l *Log) Commit(b Batch) (uint64, error) {
1017		l.mu.Lock()
1018		defer l.mu.Unlock()
1019		if l.closed {
1020			return 0, errClosed
1021		}
1022		recs, ok := l.staged[b.seq]
1023		if !ok || b.owner != l {
1024			return 0, ErrUnknownBatch
1025		}
1026		id := l.stagedID[b.seq]
1027		var entry []byte
1028		if id != "" {
1029			entry = encodeKeyedBatch(b.seq, id, recs)
1030		} else {
1031			entry = encodeBatch(b.seq, recs)
1032		}
1033		// Both single-batch encodings put the indexed body (seq onward)
1034		// right after the 4-byte magic.
1035		bodyOff := len(segmentMagic)
1036		idxBefore := l.idxSize
1037		off, err := l.writeEntry(entry)
1038		if err != nil {
1039			return 0, err
1040		}
1041		if l.opts.Sync {
1042			if err := syncFile(l.file); err != nil {
1043				// The batch stays staged and keeps its reserved sequence;
1044				// a later Commit retries. Drop the un-synced entry so the
1045				// retry cannot duplicate it on disk.
1046				l.rollbackEntry(off, idxBefore)
1047				return 0, fmt.Errorf("%w: %v", ErrSyncFailed, err)
1048			}
1049		}
1050		rec := encodeEntryRecord(indexEntry{
1051			seg:     l.segIndex,
1052			off:     off,
1053			length:  len(entry),
1054			diskCRC: binary.LittleEndian.Uint32(entry[len(entry)-4:]),
1055			keyed:   id != "",
1056			members: []indexMember{{
1057				seq: b.seq, id: id, off: off + bodyOff,
1058				length: len(entry) - bodyOff - 4,
1059			}},
1060		})
1061		if err := l.appendIndexRecord(rec); err != nil {
1062			// Index write/fsync failed: the commit is not published. Roll
1063			// the index record and the segment entry both back so a retry
1064			// republishes exactly once.
1065			l.rollbackEntry(off, idxBefore)
1066			return 0, err
1067		}
1068		delete(l.staged, b.seq)
1069		delete(l.stagedID, b.seq)
1070		l.gen++
1071		l.index[b.seq] = entryRef{
1072			seg: l.segIndex, off: off + bodyOff, length: len(entry) - bodyOff - 4,
1073			gen: l.gen, id: id, keyed: id != "",
1074		}
1075		l.commitSpan(b.seq, b.seq, 1)
1076		return b.seq, nil
1077	}
1078	
1079	// CommitGroup makes several staged batches durable and readable as one
1080	// atomic unit: a single segment write and, with Options.Sync, a single
1081	// segment fsync covering the whole group, followed by one index record
1082	// synced once. Each batch keeps the sequence it reserved at Append, and
1083	// the batches become visible in that reserved order — the merge never
1084	// reorders them. If any batch is not staged — including one already
1085	// committed — nothing is written and the error is ErrUnknownBatch. If
1086	// either fsync fails, the segment entry and the index record are rolled
1087	// back and every batch stays staged with its reserved sequence; the
1088	// error is ErrSyncFailed and retrying the group commits it without
1089	// duplicating entries. A crash can never leave half of the group
1090	// visible: the group is either wholly durable or wholly staged, and
1091	// sequences reserved by a torn group stay permanent holes.
1092	func (l *Log) CommitGroup(batches []Batch) ([]uint64, error) {
1093		l.mu.Lock()
1094		defer l.mu.Unlock()
1095		if l.closed {
1096			return nil, errClosed
1097		}
1098		if len(batches) == 0 {
1099			return nil, nil
1100		}
1101		members := make([]groupMember, len(batches))
1102		seqs := make([]uint64, len(batches))
1103		seen := make(map[uint64]struct{}, len(batches))
1104		keyed := false
1105		for i, b := range batches {
1106			recs, ok := l.staged[b.seq]
1107			if !ok || b.owner != l {
1108				return nil, ErrUnknownBatch
1109			}
1110			if _, dup := seen[b.seq]; dup {
1111				return nil, ErrUnknownBatch
1112			}
1113			seen[b.seq] = struct{}{}
1114			id := l.stagedID[b.seq]
1115			if id != "" {
1116				keyed = true
1117			}
1118			members[i] = groupMember{seq: b.seq, id: id, records: recs}
1119			seqs[i] = b.seq
1120		}
1121		entry, offs, lens := encodeGroup(members)
1122		idxBefore := l.idxSize
1123		base, err := l.writeEntry(entry)
1124		if err != nil {
1125			return nil, err
1126		}
1127		if l.opts.Sync {
1128			if err := syncFile(l.file); err != nil {
1129				// Every batch stays staged and keeps its reserved sequence;
1130				// a later CommitGroup retries. Drop the un-synced group
1131				// entry so the retry cannot duplicate it.
1132				l.rollbackEntry(base, idxBefore)
1133				return nil, fmt.Errorf("%w: %v", ErrSyncFailed, err)
1134			}
1135		}
1136		imembers := make([]indexMember, len(members))
1137		for i, m := range members {
1138			imembers[i] = indexMember{seq: m.seq, id: m.id, off: base + offs[i], length: lens[i]}
1139		}
1140		rec := encodeEntryRecord(indexEntry{
1141			seg:     l.segIndex,
1142			off:     base,
1143			length:  len(entry),
1144			diskCRC: binary.LittleEndian.Uint32(entry[len(entry)-4:]),
1145			keyed:   keyed,
1146			members: imembers,
1147		})
1148		if err := l.appendIndexRecord(rec); err != nil {
1149			// The index never advertises a batch whose commit failed: roll
1150			// both files back and leave the whole group staged for retry.
1151			l.rollbackEntry(base, idxBefore)
1152			return nil, err
1153		}
1154		first, last := seqs[0], seqs[0]
1155		l.gen++
1156		for i, m := range members {
1157			delete(l.staged, m.seq)
1158			delete(l.stagedID, m.seq)
1159			l.index[m.seq] = entryRef{
1160				seg: l.segIndex, off: base + offs[i], length: lens[i],
1161				gen: l.gen, id: m.id, keyed: keyed,
1162			}
1163			if m.seq < first {
1164				first = m.seq
1165			}
1166			if m.seq > last {
1167				last = m.seq
1168			}
1169		}
1170		l.commitSpan(first, last, len(members))
1171		return seqs, nil
1172	}
1173	
1174	// Read returns the records of the committed batch with the given
1175	// sequence, located directly through the segment-level index. A staged
1176	// but uncommitted sequence yields ErrNotCommitted; sequence 0,
1177	// never-reserved sequences, and sequences beyond the reserved range
1178	// yield ErrUnknownBatch.
1179	//
1180	// The lock is held only for the index lookup; the segment file is read
1181	// and the body decoded without it, so a slow read never blocks writers.
1182	func (l *Log) Read(seq uint64) ([][]byte, error) {
1183		l.mu.RLock()
1184		if l.closed {
1185			l.mu.RUnlock()
1186			return nil, errClosed
1187		}
1188		ref, ok := l.index[seq]
1189		if !ok {
1190			_, staged := l.staged[seq]
1191			l.mu.RUnlock()
1192			if staged {
1193				return nil, ErrNotCommitted
1194			}
1195			return nil, ErrUnknownBatch
1196		}
1197		l.mu.RUnlock()
1198		records, _, err := l.readRef(seq, ref)
1199		return records, err
1200	}
1201	
1202	// scanSnapshot is a read-consistent visibility boundary: a batch is
1203	// visible only when its publication generation is <= gen and its
1204	// sequence is <= highSeq. The boundary is captured in one brief
1205	// read-lock acquisition, so a group that commits after a replay starts
1206	// (even one filling an earlier reserved hole) is either wholly inside
1207	// the snapshot or wholly outside it.
1208	type scanSnapshot struct {
1209		gen     uint64
1210		highSeq uint64
1211	}
1212	
1213	// Scan replays committed batches with sequence >= from in increasing
1214	// sequence order, stopping at the first error returned by fn.
1215	//
1216	// The replay is a consistent snapshot: batches committed after the
1217	// replay starts are invisible to it, and a group commit is seen either
1218	// whole or not at all. The replay streams batches straight from the
1219	// segment files one sequence at a time and keeps only the current
1220	// batch in memory; it never loads the whole replay first. Each
1221	// sequence lookup takes the lock briefly, while the file read, decode
1222	// and the fn callback all run outside it, so a long replay never
1223	// blocks writers.
1224	func (l *Log) Scan(from uint64, fn func(Batch) error) error {
1225		l.mu.RLock()
1226		if l.closed {
1227			l.mu.RUnlock()
1228			return errClosed
1229		}
1230		snap := scanSnapshot{gen: l.gen, highSeq: l.nextSeq - 1}
1231		l.mu.RUnlock()
1232	
1233		if from > snap.highSeq {
1234			return nil
1235		}
1236		for seq := from; ; {
1237			// One brief read-lock per sequence: only the index metadata is
1238			// touched while holding it.
1239			l.mu.RLock()
1240			ref, ok := l.index[seq]
1241			l.mu.RUnlock()
1242			// Skip holes (reserved but uncommitted sequences) and batches
1243			// published after the snapshot was taken.
1244			if ok && ref.gen <= snap.gen {
1245				records, id, err := l.readRef(seq, ref)
1246				if err != nil {
1247					return err
1248				}
1249				if err := fn(Batch{seq: seq, id: id, records: records, owner: l}); err != nil {
1250					return err
1251				}
1252			}
1253			if seq == snap.highSeq {
1254				break
1255			}
1256			seq++
1257		}
1258		return nil
1259	}
1260	
1261	// Segments lists the segments that hold committed batches, in file
1262	// order, each with its first and last committed sequence.
1263	func (l *Log) Segments() []Segment {
1264		l.mu.RLock()
1265		defer l.mu.RUnlock()
1266		out := make([]Segment, len(l.segs))
1267		copy(out, l.segs)
1268		return out
1269	}
1270	
1271	// Close closes the current segment file and the index sidecar. The log
1272	// must not be used afterwards.
1273	func (l *Log) Close() error {
1274		l.mu.Lock()
1275		defer l.mu.Unlock()
1276		if l.closed {
1277			return nil
1278		}
1279		l.closed = true
1280		var err error
1281		if l.file != nil {
1282			err = l.file.Close()
1283		}
1284		if l.idxFile != nil {
1285			if ierr := l.idxFile.Close(); err == nil {
1286				err = ierr
1287			}
1288		}
1289		return err
1290	}
1291	
1292	// readRef loads the records of a committed batch straight from its
1293	// segment file. It acquires no locks itself; the ordinary read path
1294	// calls it without l.mu held so a slow read never blocks writers.
1295	// AppendIdempotent also calls it while holding the write lock: that
1296	// writer is the single writer and the brief locked file read is the
1297	// exact byte-for-byte conflict check. The on-disk bytes are immutable
1298	// once committed (only the torn tail of the very last segment is ever
1299	// rewritten, and that tail never has an index entry), so a ref captured
1300	// under the read lock stays valid afterwards. The returned records are
1301	// freshly decoded, so callers can mutate them without affecting the log
1302	// or later reads. Keyed bodies also return the stored key.
1303	func (l *Log) readRef(seq uint64, ref entryRef) ([][]byte, string, error) {
1304		f, err := os.Open(l.segmentPath(ref.seg))
1305		if err != nil {
1306			return nil, "", err
1307		}
1308		defer f.Close()
1309		body := make([]byte, ref.length)
1310		if _, err := f.ReadAt(body, int64(ref.off)); err != nil {
1311			return nil, "", err
1312		}
1313		if ref.keyed {
1314			got, id, records, err := decodeKeyedBody(body)
1315			if err != nil {
1316				return nil, "", err
1317			}
1318			if got != seq || id != ref.id {
1319				return nil, "", ErrCorruptSegment
1320			}
1321			return records, id, nil
1322		}
1323		got, records, err := decodeBody(body)
1324		if err != nil {
1325			return nil, "", err
1326		}
1327		if got != seq {
1328			return nil, "", ErrCorruptSegment
1329		}
1330		return records, "", nil
1331	}
1332	
1333	// commitSpan records n newly committed batches covering sequences
1334	// [first, last] in the segment listing.
1335	func (l *Log) commitSpan(first, last uint64, n int) {
1336		if l.curBatches == 0 {
1337			l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
1338		} else {
1339			seg := &l.segs[len(l.segs)-1]
1340			if first < seg.FirstSeq {
1341				seg.FirstSeq = first
1342			}
1343			if last > seg.LastSeq {
1344				seg.LastSeq = last
1345			}
1346		}
1347		l.curBatches += n
1348	}
1349	
1350	// rollbackEntry undoes a commit that failed after its segment entry was
1351	// written: the segment file is truncated back to segOff and the just
1352	// appended index sidecar record back to idxSize. The batches involved
1353	// remain staged and a retry writes each entry exactly once.
1354	func (l *Log) rollbackEntry(segOff, idxSize int) {
1355		if l.file != nil {
1356			l.file.Truncate(int64(segOff))
1357			l.fileSize = segOff
1358		}
1359		l.truncateIndex(idxSize)
1360	}
1361	
1362	// rewriteTail drops a torn tail from segment n and, when the torn entry
1363	// carried recoverable sequences, replaces it with a synced hole marker
1364	// so the reserved sequences stay permanent holes across reopens.
1365	func (l *Log) rewriteTail(n, off int, seqs []uint64) error {
1366		path := l.segmentPath(n)
1367		if err := os.Truncate(path, int64(off)); err != nil {
1368			return err
1369		}
1370		keep := make([]uint64, 0, len(seqs))
1371		for _, seq := range seqs {
1372			if seq > 0 {
1373				keep = append(keep, seq)
1374			}
1375		}
1376		if len(keep) == 0 {
1377			return nil
1378		}
1379		f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
1380		if err != nil {
1381			return err
1382		}
1383		if _, err := f.Write(encodeHoles(keep)); err != nil {
1384			f.Close()
1385			return err
1386		}
1387		if err := f.Sync(); err != nil {
1388			f.Close()
1389			return err
1390		}
1391		return f.Close()
1392	}
1393	
1394	// writeEntry appends one encoded entry to the current segment, rolling
1395	// to a new segment when the current one is non-empty and would exceed
1396	// the configured capacity, and returns the offset the entry was
1397	// written at.
1398	func (l *Log) writeEntry(entry []byte) (int, error) {
1399		if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
1400			if err := l.file.Close(); err != nil {
1401				return 0, err
1402			}
1403			l.file = nil
1404			l.segIndex++
1405			l.curBatches = 0
1406		}
1407		if l.file == nil {
1408			if l.segIndex == 0 {
1409				l.segIndex = 1
1410			}
1411			if err := l.openCurrent(); err != nil {
1412				return 0, err
1413			}
1414		}
1415		off := l.fileSize
1416		n, err := l.file.Write(entry)
1417		if err != nil {
1418			return 0, err
1419		}
1420		l.fileSize += n
1421		return off, nil
1422	}
1423	
1424	func (l *Log) openCurrent() error {
1425		f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
1426		if err != nil {
1427			return err
1428		}
1429		st, err := f.Stat()
1430		if err != nil {
1431			f.Close()
1432			return err
1433		}
1434		l.file = f
1435		l.fileSize = int(st.Size())
1436		return nil
1437	}
1438	
1439	func (l *Log) segmentPath(index int) string {
1440		return filepath.Join(l.dir, fmt.Sprintf("%06d.seg", index))
1441	}
1442	
1443	// indexPath is the persistent index sidecar, one file per log directory.
1444	func (l *Log) indexPath() string {
1445		return filepath.Join(l.dir, "index.idx")
1446	}
1447	
1448	// syncDir fsyncs the log directory so a freshly renamed sidecar (or
1449	// created segment file) is durable itself. Best effort on filesystems
1450	// that cannot fsync directories.
1451	func syncDir(dir string) error {
1452		d, err := os.Open(dir)
1453		if err != nil {
1454			return err
1455		}
1456		err = d.Sync()
1457		if cerr := d.Close(); err == nil {
1458			err = cerr
1459		}
1460		return err
1461	}
1462	
1463	func copyRecords(records [][]byte) [][]byte {
1464		out := make([][]byte, len(records))
1465		for i, r := range records {
1466			cp := make([]byte, len(r))
1467			copy(cp, r)
1468			out[i] = cp
1469		}
1470		return out
1471	}
1472

