// Package log implements an append-only, batch-commit segmented log.
//
// A writer stages a batch of opaque records with Append and publishes it
// atomically with Commit, or publishes several staged batches atomically
// with CommitGroup. AppendIdempotent stages a batch under a caller key:
// repeating a key with byte-identical records returns the first batch
// and its sequence across retries and restarts, while different records
// conflict. Readers only ever see committed batches, in strictly
// increasing sequence order starting at 1. Reads locate each batch
// through a persistent segment-level index in a sidecar file
// ("index.idx"): Open adopts it incrementally, and when it is missing,
// truncated, version-mismatched, checksum-bad or contradictory to the
// segments, Open rebuilds it from the segment files, so losing the
// index never loses data — idempotency keys live in the segments, not
// in the sidecar, and are recovered on every open path.
package log

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"sync"
	"unicode/utf8"
)

var (
	// ErrNotCommitted is returned when reading a sequence that has been
	// staged with Append but not yet committed.
	ErrNotCommitted = errors.New("log: batch not committed")
	// ErrUnknownBatch is returned for sequence 0, sequences that were
	// never reserved, sequences beyond the reserved range, and batches
	// that have already been committed.
	ErrUnknownBatch = errors.New("log: unknown batch")
	// ErrCorruptSegment is returned when a segment file fails validation
	// while opening or scanning the log.
	ErrCorruptSegment = errors.New("log: corrupt segment")
	// ErrInvalidOptions is returned by Open when the options are not
	// usable, e.g. a non-positive segment capacity.
	ErrInvalidOptions = errors.New("log: invalid options")
	// ErrSyncFailed is returned by Commit and CommitGroup when
	// Options.Sync is set and fsyncing the segment file fails. The
	// batches stay staged and keep their reserved sequences; committing
	// them again retries.
	ErrSyncFailed = errors.New("log: sync failed")
	// ErrInvalidBatchID is returned by AppendIdempotent for an empty
	// key, a key containing a NUL byte, a key that is not valid UTF-8 or
	// a key longer than 256 bytes.
	ErrInvalidBatchID = errors.New("log: invalid batch id")
	// ErrBatchIDConflict is returned by AppendIdempotent when a key was
	// used before but the new records differ from the first call's in
	// length, order or bytes.
	ErrBatchIDConflict = errors.New("log: batch id conflict")
)

var errClosed = errors.New("log: closed")

// syncFile fsyncs a segment file. It is a variable so tests can
// simulate sync failures.
var syncFile = func(f *os.File) error { return f.Sync() }

// Options configures a Log opened with Open.
type Options struct {
	// SegmentBytes is the capacity of one segment file in bytes. Once a
	// non-empty segment would exceed it, the log rolls to a new segment.
	// A single batch or group larger than the capacity occupies its own
	// segment. Must be positive.
	SegmentBytes int
	// Sync makes Commit and CommitGroup fsync the segment file before
	// returning, so a returned commit is durable.
	Sync bool
}

// Batch is a group of records identified by a single sequence number.
// A Batch returned by Append is staged; after Commit or CommitGroup it
// is readable. A batch staged with AppendIdempotent additionally
// carries the caller-chosen idempotency key, returned by ID; anonymous
// batches return "" from ID.
type Batch struct {
	seq     uint64
	id      string
	records [][]byte
	owner   *Log
}

// Seq returns the sequence number reserved for the batch.
func (b Batch) Seq() uint64 { return b.seq }

// ID returns the batch's idempotency key as given to
// AppendIdempotent, or "" for an anonymous batch staged with Append.
func (b Batch) ID() string { return b.id }

// Records returns a copy of the batch's records.
func (b Batch) Records() [][]byte { return copyRecords(b.records) }

// Segment describes one segment file by the committed sequences it holds.
type Segment struct {
	FirstSeq uint64
	LastSeq  uint64
}

// entryRef locates one committed batch body inside a segment file. The
// persistent index sidecar stores the same locations; its loss or
// invalidation is always safe because Open rebuilds it from the
// segments. gen is the publication generation of the commit that
// published the batch; every member of a group commit shares one gen,
// which lets a streaming replay snapshot see the whole group or none of
// it.
type entryRef struct {
	seg    int // segment file number
	off    int // offset of the batch body within the segment
	length int // length of the batch body
	gen    uint64
	id     string // idempotency key, "" for an anonymous batch
	keyed  bool   // body uses key framing (BCLI, or any BCLK member)
}

// Log is an append-only batch-commit log stored in a directory of
// segment files. It is safe for concurrent use, but the writer side is
// expected to be a single goroutine (see README Limits).
//
// The read and write paths are decoupled: writers take mu exclusively,
// while readers hold it only for the brief index and staged-state
// lookups. Segment file reads, decoding and user callbacks happen
// outside the lock, so a slow reader or a long replay never blocks a
// committing writer.
type Log struct {
	dir  string
	opts Options

	// mu guards the mutable index and write state below. Readers never
	// hold it across file I/O, decoding or callbacks.
	mu         sync.RWMutex
	file       *os.File // current segment, nil until first write
	fileSize   int
	idxFile    *os.File // index sidecar, opened for append
	idxSize    int
	segIndex   int // index of the current segment file, 0 = none yet
	curBatches int // committed batches in the current segment
	nextSeq    uint64
	staged     map[uint64][][]byte
	stagedID   map[uint64]string // idempotency key of staged keyed batches
	ids        map[string]uint64 // key -> seq of staged or committed keyed batch
	index      map[uint64]entryRef
	segs       []Segment // segments holding at least one committed batch
	gen        uint64    // publication generation of the last commit
	closed     bool
}

// Open opens the log in dir, creating the directory if needed. The
// committed set is taken from the persistent index sidecar when it can
// be adopted incrementally; if the sidecar is missing, truncated, from
// another version, checksum-bad or contradictory to the segment files,
// Open transparently rebuilds it by scanning the segments once. Either
// path yields identical reads, replays, segment listings and errors.
//
// A half-written tail of the last segment — the remnant of a crash
// mid-write — is replaced by a durable hole marker without error and
// its reserved sequences stay permanent holes across reopens; any other
// inconsistency is ErrCorruptSegment.
func Open(dir string, opts Options) (*Log, error) {
	if opts.SegmentBytes <= 0 {
		return nil, ErrInvalidOptions
	}
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}
	var indices []int
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".seg") {
			continue
		}
		n, err := strconv.Atoi(strings.TrimSuffix(e.Name(), ".seg"))
		if err != nil {
			continue
		}
		indices = append(indices, n)
	}
	sort.Ints(indices)

	l := &Log{
		dir:      dir,
		opts:     opts,
		nextSeq:  1,
		staged:   make(map[uint64][][]byte),
		stagedID: make(map[uint64]string),
		ids:      make(map[string]uint64),
		index:    make(map[uint64]entryRef),
	}

	// Segment sizes are all the segment metadata adoption needs; the
	// contents are touched only by the cheap CRC pass, never decoded
	// entry by entry.
	sizes := make(map[int]int, len(indices))
	for _, n := range indices {
		st, err := os.Stat(l.segmentPath(n))
		if err != nil {
			return nil, err
		}
		sizes[n] = int(st.Size())
	}

	snapshot, ok := l.adoptIndex(indices, sizes)
	if !ok {
		snapshot, err = l.rebuildFromSegments(indices)
		if err != nil {
			return nil, err
		}
	}
	sortIndexSnapshot(&snapshot)
	if err := l.installSnapshot(snapshot, indices); err != nil {
		return nil, err
	}

	if len(indices) > 0 {
		l.segIndex = indices[len(indices)-1]
		if err := l.openCurrent(); err != nil {
			return nil, err
		}
	}
	if err := l.openIndex(); err != nil {
		return nil, err
	}
	return l, nil
}

// installSnapshot populates the in-memory index, segment listing, staged
// holes, key map and next-sequence counter from an adopted or rebuilt
// snapshot. Both open paths funnel through here so their observable
// state is identical. Entries must be ordered by (segment, disk offset);
// each entry (a single commit or one group) gets one publication
// generation. A key claimed by two complete entries, or a complete
// entry whose member framing disagrees with the index, is corruption.
func (l *Log) installSnapshot(p parsedIndex, indices []int) error {
	for i := range p.entries {
		e := &p.entries[i]
		l.gen++
		for _, m := range e.members {
			l.index[m.seq] = entryRef{
				seg: e.seg, off: m.off, length: m.length, gen: l.gen,
				id: m.id, keyed: e.keyed,
			}
			if m.id != "" {
				if _, dup := l.ids[m.id]; dup {
					return ErrCorruptSegment
				}
				l.ids[m.id] = m.seq
			}
			if m.seq >= l.nextSeq {
				l.nextSeq = m.seq + 1
			}
		}
	}
	// Segment listing: one entry per physical segment that holds at
	// least one committed batch.
	segSeen := make(map[int]int)
	for i := range p.entries {
		e := &p.entries[i]
		var first, last uint64
		for j, m := range e.members {
			if j == 0 {
				first, last = m.seq, m.seq
			}
			if m.seq < first {
				first = m.seq
			}
			if m.seq > last {
				last = m.seq
			}
		}
		if idx, known := segSeen[e.seg]; known {
			if first < l.segs[idx].FirstSeq {
				l.segs[idx].FirstSeq = first
			}
			if last > l.segs[idx].LastSeq {
				l.segs[idx].LastSeq = last
			}
		} else {
			segSeen[e.seg] = len(l.segs)
			l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
		}
	}
	// Holes reserve sequences permanently: they read as staged (never
	// committed) and are never reused, across any number of reopens.
	for i := range p.holes {
		for _, seq := range p.holes[i].seqs {
			if seq == 0 {
				continue
			}
			if _, committed := l.index[seq]; !committed {
				l.staged[seq] = nil
			}
			if seq >= l.nextSeq {
				l.nextSeq = seq + 1
			}
		}
	}
	if len(indices) > 0 {
		last := indices[len(indices)-1]
		l.curBatches = 0
		for i := range p.entries {
			if p.entries[i].seg == last {
				l.curBatches += len(p.entries[i].members)
			}
		}
	}
	return nil
}

// sortIndexSnapshot orders a snapshot's records by (segment, offset),
// the canonical on-disk and publication order.
func sortIndexSnapshot(p *parsedIndex) {
	sort.SliceStable(p.entries, func(i, j int) bool {
		if p.entries[i].seg != p.entries[j].seg {
			return p.entries[i].seg < p.entries[j].seg
		}
		return p.entries[i].off < p.entries[j].off
	})
	sort.SliceStable(p.holes, func(i, j int) bool {
		if p.holes[i].seg != p.holes[j].seg {
			return p.holes[i].seg < p.holes[j].seg
		}
		return p.holes[i].off < p.holes[j].off
	})
}

// adoptIndex is the incremental open path. It verifies the sidecar
// against the segment files without decoding record bodies: its records
// must tile a prefix of the segment files from offset zero, every
// on-disk CRC must match, and member locations must agree with the entry
// headers. Any framing defect, a truncated final record, a version
// mismatch or a contradiction makes it return ok=false and Open rebuilds
// from the segments instead.
//
// The segments may legitimately extend past a verified index — the
// crash window between the segment sync and the index record sync. That
// suffix (extra bytes of the last covered segment, plus any whole later
// segment) is parsed incrementally: complete entries get indexed, a
// torn tail of the last segment becomes a hole marker, so adoption
// still costs one small decode rather than a full scan.
func (l *Log) adoptIndex(indices []int, sizes map[int]int) (parsedIndex, bool) {
	if len(indices) == 0 {
		// No segments: nothing to index; openIndex creates the sidecar
		// lazily with its header when the first commit lands.
		return parsedIndex{}, true
	}
	data, err := l.readIndexBytes()
	if err != nil {
		return parsedIndex{}, false
	}
	p, tailLen, err := readIndexFile(data)
	if err != nil || tailLen > 0 {
		// Missing/truncated/foreign sidecar: the rebuild path owns
		// these cases.
		return parsedIndex{}, false
	}
	if len(p.entries) == 0 && len(p.holes) == 0 {
		// A recordless sidecar is valid only when every segment is
		// empty; otherwise the sidecar is simply behind and the
		// rebuild path catches up.
		for _, n := range indices {
			if sizes[n] != 0 {
				return parsedIndex{}, false
			}
		}
		return p, true
	}
	covered, covEnd, ok := l.verifySidecar(p, indices, sizes)
	if !ok {
		return parsedIndex{}, false
	}

	// Everything at or after covered is unverified suffix: the unindexed
	// tail bytes of segment covered, then every whole later segment.
	pos := 0
	for pos < len(indices) && indices[pos] < covered {
		pos++
	}
	var extra []diskRecord
	for si := pos; si < len(indices); si++ {
		n := indices[si]
		raw, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return parsedIndex{}, false
		}
		base := 0
		if n == covered {
			if covEnd > len(raw) {
				return parsedIndex{}, false
			}
			base = covEnd
		}
		batches, markers, tail, perr := parseSegment(raw[base:])
		if perr != nil {
			// Tampering in the suffix surfaces through the rebuild path
			// with the identical ErrCorruptSegment.
			return parsedIndex{}, false
		}
		if tail != nil && si != len(indices)-1 {
			return parsedIndex{}, false
		}
		for k := 0; k < len(batches); {
			diskOff := batches[k].diskOff + base
			j := k + 1
			for j < len(batches) && batches[j].diskOff+base == diskOff {
				j++
			}
			e := indexEntry{
				seg:     n,
				off:     diskOff,
				length:  batches[k].diskLen,
				diskCRC: batches[k].diskCRC,
				keyed:   batches[k].keyed,
				members: make([]indexMember, 0, j-k),
			}
			for _, pb := range batches[k:j] {
				e.members = append(e.members, indexMember{
					seq: pb.seq, id: pb.id, off: pb.off + base, length: pb.length,
				})
			}
			p.entries = append(p.entries, e)
			extra = append(extra, diskRecord{seg: n, off: diskOff, enc: encodeEntryRecord(e)})
			k = j
		}
		for _, h := range markers {
			ih := indexHole{
				seg: n, off: h.off + base, length: h.length, diskCRC: h.crc,
				seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
			}
			p.holes = append(p.holes, ih)
			extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
		}
		if tail != nil {
			keep := make([]uint64, 0, len(tail.seqs))
			for _, seq := range tail.seqs {
				if seq > 0 {
					keep = append(keep, seq)
				}
			}
			if err := l.rewriteTail(n, base+tail.off, keep); err != nil {
				return parsedIndex{}, false
			}
			if len(keep) > 0 {
				marker := encodeHoles(keep)
				crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
				ih := indexHole{
					seg: n, off: base + tail.off, length: len(marker), diskCRC: crc,
					seqs: append(make([]uint64, 0, len(keep)), keep...),
				}
				p.holes = append(p.holes, ih)
				extra = append(extra, diskRecord{seg: n, off: ih.off, enc: encodeHoleRecord(ih)})
			}
		}
	}

	// Persist the incrementally recovered records so later opens adopt
	// them too. A crash during this append leaves a torn final index
	// record, and the next open simply rebuilds.
	if len(extra) > 0 {
		if err := l.appendAdoptedSuffix(extra); err != nil {
			return parsedIndex{}, false
		}
	}
	return p, true
}

// appendAdoptedSuffix appends incrementally recovered records to the
// sidecar and fsyncs it. Failure means the caller rebuilds instead.
func (l *Log) appendAdoptedSuffix(recs []diskRecord) error {
	sort.SliceStable(recs, func(i, j int) bool {
		if recs[i].seg != recs[j].seg {
			return recs[i].seg < recs[j].seg
		}
		return recs[i].off < recs[j].off
	})
	f, err := os.OpenFile(l.indexPath(), os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	defer f.Close()
	for _, r := range recs {
		if _, err := f.Write(r.enc); err != nil {
			return err
		}
	}
	return f.Sync()
}

// sidecarRec is one physical record the index claims.
type sidecarRec struct {
	seg    int
	off    int
	length int
	crc    uint32
	entry  *indexEntry
	hole   *indexHole
}

// verifySidecar checks an already-framed parse against the physical
// segments without decoding any record body. It returns the last segment
// the index covers and the offset immediately after its records there.
//
// The covered segments must be a prefix of the segment files in the
// directory; within each one records must be strictly ordered, start at
// offset zero and tile without gaps or overlap. Every covered segment
// except the last must end exactly at the file size (nothing
// unindexed); the last one may stop short, leaving a suffix for
// incremental parsing. Every stored disk CRC is recomputed, and entry
// headers (magic and group membership layout) are checked.
func (l *Log) verifySidecar(p parsedIndex, indices []int, sizes map[int]int) (coveredSeg int, coveredEnd int, ok bool) {
	if len(indices) == 0 {
		return 0, 0, false
	}
	recs := make([]sidecarRec, 0, len(p.entries)+len(p.holes))
	for i := range p.entries {
		e := &p.entries[i]
		recs = append(recs, sidecarRec{seg: e.seg, off: e.off, length: e.length, crc: e.diskCRC, entry: e})
	}
	for i := range p.holes {
		h := &p.holes[i]
		recs = append(recs, sidecarRec{seg: h.seg, off: h.off, length: h.length, crc: h.diskCRC, hole: h})
	}
	sort.SliceStable(recs, func(i, j int) bool {
		if recs[i].seg != recs[j].seg {
			return recs[i].seg < recs[j].seg
		}
		return recs[i].off < recs[j].off
	})

	known := make(map[int]bool, len(indices))
	for _, n := range indices {
		known[n] = true
	}
	covered := false
	seenSeq := make(map[uint64]bool)
	seenKey := make(map[string]bool)
	var f *os.File
	openSeg := -1
	closeFile := func() {
		if f != nil {
			f.Close()
			f = nil
			openSeg = -1
		}
	}
	defer closeFile()

	prevSeg, prevEnd := -1, 0
	for i := range recs {
		r := &recs[i]
		if !known[r.seg] || r.off < 0 || r.length < 16 {
			return 0, 0, false
		}
		if r.seg != prevSeg {
			// A new covered segment: the previous one must be tiled to
			// its EOF, and the covered segments must be a prefix with no
			// unindexed segment file in between.
			if prevSeg != -1 && prevEnd != sizes[prevSeg] {
				return 0, 0, false
			}
			if covered {
				next := 0
				found := false
				for _, n := range indices {
					if n > prevSeg {
						next, found = n, true
						break
					}
				}
				if !found || r.seg != next || r.off != 0 {
					return 0, 0, false
				}
			} else {
				if r.seg != indices[0] || r.off != 0 {
					return 0, 0, false
				}
			}
			covered = true
			prevSeg = r.seg
			prevEnd = 0
			closeFile()
			var err error
			f, err = os.Open(l.segmentPath(r.seg))
			if err != nil {
				return 0, 0, false
			}
			openSeg = r.seg
		}
		if openSeg != r.seg || r.off != prevEnd || r.off+r.length > sizes[r.seg] {
			return 0, 0, false
		}
		if !l.verifyDiskRecord(f, r, seenSeq, seenKey) {
			return 0, 0, false
		}
		prevEnd = r.off + r.length
	}
	lastSeg := recs[len(recs)-1].seg
	lastEnd := prevEnd

	// Every segment file before the last covered one must carry at
	// least one index record (no unindexed segment in the middle).
	refSegs := map[int]bool{}
	for i := range recs {
		refSegs[recs[i].seg] = true
	}
	for _, n := range indices {
		if n < lastSeg && !refSegs[n] {
			return 0, 0, false
		}
	}
	return lastSeg, lastEnd, true
}

// verifyDiskRecord checks one index claim against the segment without
// holding the entry in memory: a small header read, a streaming CRC over
// a fixed-size scratch buffer, and small reads of group-member sequences
// and key frames. It never decodes record bodies.
func (l *Log) verifyDiskRecord(f *os.File, r *sidecarRec, seenSeq map[uint64]bool, seenKey map[string]bool) bool {
	var hdr [16]byte
	if _, err := f.ReadAt(hdr[:12], int64(r.off)); err != nil {
		return false
	}
	// Stream the entry's CRC-covered prefix through one reused buffer,
	// then compare against the stored trailing checksum.
	h := crc32.NewIEEE()
	buf := make([]byte, 64*1024)
	remaining := r.length - 4
	at := int64(r.off)
	for remaining > 0 {
		n := len(buf)
		if n > remaining {
			n = remaining
		}
		if _, err := f.ReadAt(buf[:n], at); err != nil {
			return false
		}
		h.Write(buf[:n])
		remaining -= n
		at += int64(n)
	}
	var crcBytes [4]byte
	if _, err := f.ReadAt(crcBytes[:], at); err != nil {
		return false
	}
	stored := binary.LittleEndian.Uint32(crcBytes[:])
	if h.Sum32() != stored || stored != r.crc {
		return false
	}

	switch {
	case r.entry != nil:
		e := r.entry
		switch {
		case bytes.Equal(hdr[:4], segmentMagic):
			if e.keyed || len(e.members) != 1 || e.members[0].id != "" {
				return false
			}
			return len(e.members) == 1 &&
				e.members[0].seq == binary.LittleEndian.Uint64(hdr[4:12]) &&
				e.members[0].off == r.off+4 &&
				e.members[0].length == r.length-8 &&
				markSeen(e.members, seenSeq, nil)
		case bytes.Equal(hdr[:4], keyedMagic):
			if !e.keyed || len(e.members) != 1 {
				return false
			}
			m := e.members[0]
			if m.id == "" ||
				m.seq != binary.LittleEndian.Uint64(hdr[4:12]) ||
				m.off != r.off+4 || m.length != r.length-8 {
				return false
			}
			if _, ok := verifyKeyOnDisk(f, int64(m.off+8), m.id); !ok {
				return false
			}
			return markSeen(e.members, seenSeq, seenKey)
		case bytes.Equal(hdr[:4], groupMagic):
			if e.keyed {
				return false
			}
			if uint32(len(e.members)) != binary.LittleEndian.Uint32(hdr[4:8]) {
				return false
			}
			if !checkMemberLayout(r, e) {
				return false
			}
			for _, m := range e.members {
				if m.id != "" {
					return false
				}
				var seqBytes [8]byte
				if _, err := f.ReadAt(seqBytes[:], int64(m.off)); err != nil {
					return false
				}
				if m.seq != binary.LittleEndian.Uint64(seqBytes[:]) {
					return false
				}
			}
			return markSeen(e.members, seenSeq, nil)
		case bytes.Equal(hdr[:4], keyedGroup):
			if !e.keyed {
				return false
			}
			if uint32(len(e.members)) != binary.LittleEndian.Uint32(hdr[4:8]) {
				return false
			}
			if !checkMemberLayout(r, e) {
				return false
			}
			for _, m := range e.members {
				if _, ok := verifyKeyOnDisk(f, int64(m.off+8), m.id); !ok {
					return false
				}
				var seqBytes [8]byte
				if _, err := f.ReadAt(seqBytes[:], int64(m.off)); err != nil {
					return false
				}
				if m.seq != binary.LittleEndian.Uint64(seqBytes[:]) {
					return false
				}
			}
			return markSeen(e.members, seenSeq, seenKey)
		default:
			return false
		}
	case r.hole != nil:
		h2 := r.hole
		if !bytes.Equal(hdr[:4], holeMagic) ||
			uint32(len(h2.seqs)) != binary.LittleEndian.Uint32(hdr[4:8]) ||
			r.length != 4+4+8*len(h2.seqs)+4 {
			return false
		}
		// The reserved sequences themselves must agree with the marker,
		// not just their count.
		seqBytes := make([]byte, 8*len(h2.seqs))
		if len(seqBytes) > 0 {
			if _, err := f.ReadAt(seqBytes, int64(r.off+8)); err != nil {
				return false
			}
			for i, seq := range h2.seqs {
				if seq == 0 || seenSeq[seq] ||
					seq != binary.LittleEndian.Uint64(seqBytes[8*i:8*i+8]) {
					return false
				}
			}
		}
		return true
	default:
		return false
	}
}

// checkMemberLayout verifies that a group entry's member bodies tile the
// entry's CRC-covered payload with no gaps or overhang, starting right
// after the 8-byte group header.
func checkMemberLayout(r *sidecarRec, e *indexEntry) bool {
	bodyStart := r.off + 8
	for i, m := range e.members {
		rel := m.off - r.off
		if m.length <= 0 || rel < 8 || rel+m.length > r.length-4 {
			return false
		}
		if i == 0 {
			if m.off != bodyStart {
				return false
			}
		} else {
			prev := e.members[i-1]
			if m.off != prev.off+prev.length {
				return false
			}
		}
	}
	return e.members[len(e.members)-1].off+e.members[len(e.members)-1].length == r.off+r.length-4
}

// verifyKeyOnDisk reads the 2-byte key length and key bytes at off and
// checks they name exactly want ("" requires a zero length). It returns
// the on-disk key length so callers can locate the seq that follows.
func verifyKeyOnDisk(f *os.File, off int64, want string) (int, bool) {
	var lenBytes [2]byte
	if _, err := f.ReadAt(lenBytes[:], off); err != nil {
		return 0, false
	}
	klen := int(binary.LittleEndian.Uint16(lenBytes[:]))
	if want == "" {
		return 0, klen == 0
	}
	if klen != len(want) || klen > maxBatchIDLen {
		return 0, false
	}
	raw := make([]byte, klen)
	if _, err := f.ReadAt(raw, off+2); err != nil {
		return 0, false
	}
	if string(raw) != want {
		return 0, false
	}
	return klen, true
}

// markSeen records every member sequence, rejecting 0 and duplicates;
// when seenKey is non-nil it does the same for member idempotency keys.
func markSeen(members []indexMember, seen map[uint64]bool, seenKey map[string]bool) bool {
	for _, m := range members {
		if m.seq == 0 || seen[m.seq] {
			return false
		}
		seen[m.seq] = true
		if seenKey != nil && m.id != "" {
			if seenKey[m.id] {
				return false
			}
			seenKey[m.id] = true
		}
	}
	return true
}

// rebuildFromSegments is the fallback open path: it decodes every
// segment exactly as a historical open did, recovers a torn tail of the
// last segment into a durable hole marker, and finally persists a fresh
// index snapshot. Tampering anywhere but the last segment's tail stays
// ErrCorruptSegment.
func (l *Log) rebuildFromSegments(indices []int) (parsedIndex, error) {
	var p parsedIndex
	for i, n := range indices {
		data, err := os.ReadFile(l.segmentPath(n))
		if err != nil {
			return parsedIndex{}, err
		}
		batches, markers, tail, err := parseSegment(data)
		if err != nil {
			return parsedIndex{}, err
		}
		if tail != nil && i != len(indices)-1 {
			// A half-written tail is a crash remnant only in the last
			// segment; anywhere else it is tampering.
			return parsedIndex{}, ErrCorruptSegment
		}
		for k := 0; k < len(batches); {
			// Members of one group entry share diskOff; a single commit
			// is an entry with one member.
			diskOff := batches[k].diskOff
			j := k + 1
			for j < len(batches) && batches[j].diskOff == diskOff {
				j++
			}
			e := indexEntry{
				seg:     n,
				off:     batches[k].diskOff,
				length:  batches[k].diskLen,
				diskCRC: batches[k].diskCRC,
				keyed:   batches[k].keyed,
				members: make([]indexMember, 0, j-k),
			}
			for _, pb := range batches[k:j] {
				e.members = append(e.members, indexMember{seq: pb.seq, id: pb.id, off: pb.off, length: pb.length})
			}
			p.entries = append(p.entries, e)
			k = j
		}
		for _, h := range markers {
			p.holes = append(p.holes, indexHole{
				seg: n, off: h.off, length: h.length, diskCRC: h.crc,
				seqs: append(make([]uint64, 0, len(h.seqs)), h.seqs...),
			})
		}
		if tail != nil {
			// Replace the torn entry with a durable hole marker so its
			// reserved sequences stay permanent holes, then index the
			// replacement marker as part of the fresh snapshot.
			keep := make([]uint64, 0, len(tail.seqs))
			for _, seq := range tail.seqs {
				if seq > 0 {
					keep = append(keep, seq)
				}
			}
			if err := l.rewriteTail(n, tail.off, keep); err != nil {
				return parsedIndex{}, err
			}
			if len(keep) > 0 {
				marker := encodeHoles(keep)
				crc := binary.LittleEndian.Uint32(marker[len(marker)-4:])
				p.holes = append(p.holes, indexHole{
					seg: n, off: tail.off, length: len(marker), diskCRC: crc,
					seqs: append(make([]uint64, 0, len(keep)), keep...),
				})
			}
		}
	}
	sortIndexSnapshot(&p)
	if err := l.writeIndexSnapshot(p); err != nil {
		return parsedIndex{}, err
	}
	return p, nil
}

// Append stages a batch of records and reserves the next sequence number
// for it. The batch becomes readable only after Commit or CommitGroup.
func (l *Log) Append(records [][]byte) (Batch, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return Batch{}, errClosed
	}
	recs := copyRecords(records)
	seq := l.nextSeq
	l.nextSeq++
	l.staged[seq] = recs
	return Batch{seq: seq, records: recs, owner: l}, nil
}

// AppendIdempotent stages a batch under a caller-chosen key that is
// unique within the log directory, and reserves the next sequence
// number for it, exactly as Append does for anonymous batches. Repeating
// a call with a key already in use is safe across network retries and
// process restarts:
//
//   - If records match the first call in length, order and every byte,
//     the first batch is returned with its original Seq — whether it is
//     still staged or already committed. No new sequence is reserved and
//     nothing is written again.
//   - If the records differ, ErrBatchIDConflict is returned.
//
// An empty key, a key containing a NUL byte, a key that is not valid
// UTF-8, or a key longer than 256 bytes returns ErrInvalidBatchID.
func (l *Log) AppendIdempotent(key string, records [][]byte) (Batch, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return Batch{}, errClosed
	}
	if !validBatchID(key) {
		return Batch{}, ErrInvalidBatchID
	}
	recs := copyRecords(records)
	if seq, ok := l.ids[key]; ok {
		// The first call is either still staged or already committed;
		// compare against the exact bytes it owns so a retry cannot
		// reserve another sequence or write a second entry.
		var prior [][]byte
		if staged, isStaged := l.staged[seq]; isStaged {
			prior = staged
		} else {
			ref, known := l.index[seq]
			if !known {
				return Batch{}, ErrCorruptSegment
			}
			got, id, err := l.readRef(seq, ref)
			if err != nil {
				return Batch{}, err
			}
			if id != key {
				return Batch{}, ErrCorruptSegment
			}
			prior = got
		}
		if !recordsEqual(prior, recs) {
			return Batch{}, ErrBatchIDConflict
		}
		return Batch{seq: seq, id: key, records: copyRecords(prior), owner: l}, nil
	}
	seq := l.nextSeq
	l.nextSeq++
	l.staged[seq] = recs
	l.stagedID[seq] = key
	l.ids[key] = seq
	return Batch{seq: seq, id: key, records: recs, owner: l}, nil
}

// validBatchID reports whether key is an acceptable idempotency key:
// non-empty, valid UTF-8, NUL-free and at most 256 bytes long.
func validBatchID(key string) bool {
	if key == "" || len(key) > maxBatchIDLen {
		return false
	}
	if strings.IndexByte(key, 0) >= 0 {
		return false
	}
	return utf8.ValidString(key)
}

// recordsEqual reports whether two record slices agree in length, order
// and every byte.
func recordsEqual(a, b [][]byte) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if !bytes.Equal(a[i], b[i]) {
			return false
		}
	}
	return true
}

// Commit makes a staged batch durable and readable, and returns its
// reserved sequence number. Committing a batch that is not staged —
// including one already committed — returns ErrUnknownBatch. With
// Options.Sync a returned commit is durable: the segment entry and the
// index sidecar record are both synced, one fsync each. If either
// fsync fails Commit returns ErrSyncFailed, rolls both files back and
// the batch stays staged, keeping its reserved sequence for a retry
// that cannot produce a duplicate entry.
func (l *Log) Commit(b Batch) (uint64, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return 0, errClosed
	}
	recs, ok := l.staged[b.seq]
	if !ok || b.owner != l {
		return 0, ErrUnknownBatch
	}
	id := l.stagedID[b.seq]
	var entry []byte
	if id != "" {
		entry = encodeKeyedBatch(b.seq, id, recs)
	} else {
		entry = encodeBatch(b.seq, recs)
	}
	// Both single-batch encodings put the indexed body (seq onward)
	// right after the 4-byte magic.
	bodyOff := len(segmentMagic)
	idxBefore := l.idxSize
	off, err := l.writeEntry(entry)
	if err != nil {
		return 0, err
	}
	if l.opts.Sync {
		if err := syncFile(l.file); err != nil {
			// The batch stays staged and keeps its reserved sequence;
			// a later Commit retries. Drop the un-synced entry so the
			// retry cannot duplicate it on disk.
			l.rollbackEntry(off, idxBefore)
			return 0, fmt.Errorf("%w: %v", ErrSyncFailed, err)
		}
	}
	rec := encodeEntryRecord(indexEntry{
		seg:     l.segIndex,
		off:     off,
		length:  len(entry),
		diskCRC: binary.LittleEndian.Uint32(entry[len(entry)-4:]),
		keyed:   id != "",
		members: []indexMember{{
			seq: b.seq, id: id, off: off + bodyOff,
			length: len(entry) - bodyOff - 4,
		}},
	})
	if err := l.appendIndexRecord(rec); err != nil {
		// Index write/fsync failed: the commit is not published. Roll
		// the index record and the segment entry both back so a retry
		// republishes exactly once.
		l.rollbackEntry(off, idxBefore)
		return 0, err
	}
	delete(l.staged, b.seq)
	delete(l.stagedID, b.seq)
	l.gen++
	l.index[b.seq] = entryRef{
		seg: l.segIndex, off: off + bodyOff, length: len(entry) - bodyOff - 4,
		gen: l.gen, id: id, keyed: id != "",
	}
	l.commitSpan(b.seq, b.seq, 1)
	return b.seq, nil
}

// CommitGroup makes several staged batches durable and readable as one
// atomic unit: a single segment write and, with Options.Sync, a single
// segment fsync covering the whole group, followed by one index record
// synced once. Each batch keeps the sequence it reserved at Append, and
// the batches become visible in that reserved order — the merge never
// reorders them. If any batch is not staged — including one already
// committed — nothing is written and the error is ErrUnknownBatch. If
// either fsync fails, the segment entry and the index record are rolled
// back and every batch stays staged with its reserved sequence; the
// error is ErrSyncFailed and retrying the group commits it without
// duplicating entries. A crash can never leave half of the group
// visible: the group is either wholly durable or wholly staged, and
// sequences reserved by a torn group stay permanent holes.
func (l *Log) CommitGroup(batches []Batch) ([]uint64, error) {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return nil, errClosed
	}
	if len(batches) == 0 {
		return nil, nil
	}
	members := make([]groupMember, len(batches))
	seqs := make([]uint64, len(batches))
	seen := make(map[uint64]struct{}, len(batches))
	keyed := false
	for i, b := range batches {
		recs, ok := l.staged[b.seq]
		if !ok || b.owner != l {
			return nil, ErrUnknownBatch
		}
		if _, dup := seen[b.seq]; dup {
			return nil, ErrUnknownBatch
		}
		seen[b.seq] = struct{}{}
		id := l.stagedID[b.seq]
		if id != "" {
			keyed = true
		}
		members[i] = groupMember{seq: b.seq, id: id, records: recs}
		seqs[i] = b.seq
	}
	entry, offs, lens := encodeGroup(members)
	idxBefore := l.idxSize
	base, err := l.writeEntry(entry)
	if err != nil {
		return nil, err
	}
	if l.opts.Sync {
		if err := syncFile(l.file); err != nil {
			// Every batch stays staged and keeps its reserved sequence;
			// a later CommitGroup retries. Drop the un-synced group
			// entry so the retry cannot duplicate it.
			l.rollbackEntry(base, idxBefore)
			return nil, fmt.Errorf("%w: %v", ErrSyncFailed, err)
		}
	}
	imembers := make([]indexMember, len(members))
	for i, m := range members {
		imembers[i] = indexMember{seq: m.seq, id: m.id, off: base + offs[i], length: lens[i]}
	}
	rec := encodeEntryRecord(indexEntry{
		seg:     l.segIndex,
		off:     base,
		length:  len(entry),
		diskCRC: binary.LittleEndian.Uint32(entry[len(entry)-4:]),
		keyed:   keyed,
		members: imembers,
	})
	if err := l.appendIndexRecord(rec); err != nil {
		// The index never advertises a batch whose commit failed: roll
		// both files back and leave the whole group staged for retry.
		l.rollbackEntry(base, idxBefore)
		return nil, err
	}
	first, last := seqs[0], seqs[0]
	l.gen++
	for i, m := range members {
		delete(l.staged, m.seq)
		delete(l.stagedID, m.seq)
		l.index[m.seq] = entryRef{
			seg: l.segIndex, off: base + offs[i], length: lens[i],
			gen: l.gen, id: m.id, keyed: keyed,
		}
		if m.seq < first {
			first = m.seq
		}
		if m.seq > last {
			last = m.seq
		}
	}
	l.commitSpan(first, last, len(members))
	return seqs, nil
}

// Read returns the records of the committed batch with the given
// sequence, located directly through the segment-level index. A staged
// but uncommitted sequence yields ErrNotCommitted; sequence 0,
// never-reserved sequences, and sequences beyond the reserved range
// yield ErrUnknownBatch.
//
// The lock is held only for the index lookup; the segment file is read
// and the body decoded without it, so a slow read never blocks writers.
func (l *Log) Read(seq uint64) ([][]byte, error) {
	l.mu.RLock()
	if l.closed {
		l.mu.RUnlock()
		return nil, errClosed
	}
	ref, ok := l.index[seq]
	if !ok {
		_, staged := l.staged[seq]
		l.mu.RUnlock()
		if staged {
			return nil, ErrNotCommitted
		}
		return nil, ErrUnknownBatch
	}
	l.mu.RUnlock()
	records, _, err := l.readRef(seq, ref)
	return records, err
}

// scanSnapshot is a read-consistent visibility boundary: a batch is
// visible only when its publication generation is <= gen and its
// sequence is <= highSeq. The boundary is captured in one brief
// read-lock acquisition, so a group that commits after a replay starts
// (even one filling an earlier reserved hole) is either wholly inside
// the snapshot or wholly outside it.
type scanSnapshot struct {
	gen     uint64
	highSeq uint64
}

// Scan replays committed batches with sequence >= from in increasing
// sequence order, stopping at the first error returned by fn.
//
// The replay is a consistent snapshot: batches committed after the
// replay starts are invisible to it, and a group commit is seen either
// whole or not at all. The replay streams batches straight from the
// segment files one sequence at a time and keeps only the current
// batch in memory; it never loads the whole replay first. Each
// sequence lookup takes the lock briefly, while the file read, decode
// and the fn callback all run outside it, so a long replay never
// blocks writers.
func (l *Log) Scan(from uint64, fn func(Batch) error) error {
	l.mu.RLock()
	if l.closed {
		l.mu.RUnlock()
		return errClosed
	}
	snap := scanSnapshot{gen: l.gen, highSeq: l.nextSeq - 1}
	l.mu.RUnlock()

	if from > snap.highSeq {
		return nil
	}
	for seq := from; ; {
		// One brief read-lock per sequence: only the index metadata is
		// touched while holding it.
		l.mu.RLock()
		ref, ok := l.index[seq]
		l.mu.RUnlock()
		// Skip holes (reserved but uncommitted sequences) and batches
		// published after the snapshot was taken.
		if ok && ref.gen <= snap.gen {
			records, id, err := l.readRef(seq, ref)
			if err != nil {
				return err
			}
			if err := fn(Batch{seq: seq, id: id, records: records, owner: l}); err != nil {
				return err
			}
		}
		if seq == snap.highSeq {
			break
		}
		seq++
	}
	return nil
}

// Segments lists the segments that hold committed batches, in file
// order, each with its first and last committed sequence.
func (l *Log) Segments() []Segment {
	l.mu.RLock()
	defer l.mu.RUnlock()
	out := make([]Segment, len(l.segs))
	copy(out, l.segs)
	return out
}

// Close closes the current segment file and the index sidecar. The log
// must not be used afterwards.
func (l *Log) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	if l.closed {
		return nil
	}
	l.closed = true
	var err error
	if l.file != nil {
		err = l.file.Close()
	}
	if l.idxFile != nil {
		if ierr := l.idxFile.Close(); err == nil {
			err = ierr
		}
	}
	return err
}

// readRef loads the records of a committed batch straight from its
// segment file. It acquires no locks itself; the ordinary read path
// calls it without l.mu held so a slow read never blocks writers.
// AppendIdempotent also calls it while holding the write lock: that
// writer is the single writer and the brief locked file read is the
// exact byte-for-byte conflict check. The on-disk bytes are immutable
// once committed (only the torn tail of the very last segment is ever
// rewritten, and that tail never has an index entry), so a ref captured
// under the read lock stays valid afterwards. The returned records are
// freshly decoded, so callers can mutate them without affecting the log
// or later reads. Keyed bodies also return the stored key.
func (l *Log) readRef(seq uint64, ref entryRef) ([][]byte, string, error) {
	f, err := os.Open(l.segmentPath(ref.seg))
	if err != nil {
		return nil, "", err
	}
	defer f.Close()
	body := make([]byte, ref.length)
	if _, err := f.ReadAt(body, int64(ref.off)); err != nil {
		return nil, "", err
	}
	if ref.keyed {
		got, id, records, err := decodeKeyedBody(body)
		if err != nil {
			return nil, "", err
		}
		if got != seq || id != ref.id {
			return nil, "", ErrCorruptSegment
		}
		return records, id, nil
	}
	got, records, err := decodeBody(body)
	if err != nil {
		return nil, "", err
	}
	if got != seq {
		return nil, "", ErrCorruptSegment
	}
	return records, "", nil
}

// commitSpan records n newly committed batches covering sequences
// [first, last] in the segment listing.
func (l *Log) commitSpan(first, last uint64, n int) {
	if l.curBatches == 0 {
		l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
	} else {
		seg := &l.segs[len(l.segs)-1]
		if first < seg.FirstSeq {
			seg.FirstSeq = first
		}
		if last > seg.LastSeq {
			seg.LastSeq = last
		}
	}
	l.curBatches += n
}

// rollbackEntry undoes a commit that failed after its segment entry was
// written: the segment file is truncated back to segOff and the just
// appended index sidecar record back to idxSize. The batches involved
// remain staged and a retry writes each entry exactly once.
func (l *Log) rollbackEntry(segOff, idxSize int) {
	if l.file != nil {
		l.file.Truncate(int64(segOff))
		l.fileSize = segOff
	}
	l.truncateIndex(idxSize)
}

// rewriteTail drops a torn tail from segment n and, when the torn entry
// carried recoverable sequences, replaces it with a synced hole marker
// so the reserved sequences stay permanent holes across reopens.
func (l *Log) rewriteTail(n, off int, seqs []uint64) error {
	path := l.segmentPath(n)
	if err := os.Truncate(path, int64(off)); err != nil {
		return err
	}
	keep := make([]uint64, 0, len(seqs))
	for _, seq := range seqs {
		if seq > 0 {
			keep = append(keep, seq)
		}
	}
	if len(keep) == 0 {
		return nil
	}
	f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
	if err != nil {
		return err
	}
	if _, err := f.Write(encodeHoles(keep)); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	return f.Close()
}

// writeEntry appends one encoded entry to the current segment, rolling
// to a new segment when the current one is non-empty and would exceed
// the configured capacity, and returns the offset the entry was
// written at.
func (l *Log) writeEntry(entry []byte) (int, error) {
	if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
		if err := l.file.Close(); err != nil {
			return 0, err
		}
		l.file = nil
		l.segIndex++
		l.curBatches = 0
	}
	if l.file == nil {
		if l.segIndex == 0 {
			l.segIndex = 1
		}
		if err := l.openCurrent(); err != nil {
			return 0, err
		}
	}
	off := l.fileSize
	n, err := l.file.Write(entry)
	if err != nil {
		return 0, err
	}
	l.fileSize += n
	return off, nil
}

func (l *Log) openCurrent() error {
	f, err := os.OpenFile(l.segmentPath(l.segIndex), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	st, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	l.file = f
	l.fileSize = int(st.Size())
	return nil
}

func (l *Log) segmentPath(index int) string {
	return filepath.Join(l.dir, fmt.Sprintf("%06d.seg", index))
}

// indexPath is the persistent index sidecar, one file per log directory.
func (l *Log) indexPath() string {
	return filepath.Join(l.dir, "index.idx")
}

// syncDir fsyncs the log directory so a freshly renamed sidecar (or
// created segment file) is durable itself. Best effort on filesystems
// that cannot fsync directories.
func syncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return err
	}
	err = d.Sync()
	if cerr := d.Close(); err == nil {
		err = cerr
	}
	return err
}

func copyRecords(records [][]byte) [][]byte {
	out := make([][]byte, len(records))
	for i, r := range records {
		cp := make([]byte, len(r))
		copy(cp, r)
		out[i] = cp
	}
	return out
}

package log

import (
	"bytes"
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"os"
	"sort"
	"unicode/utf8"
)

// The segment-level index lives in a sidecar file ("index.idx") next to
// the segments so that Open never has to decode every segment entry as
// the log grows. The sidecar is a derived, rebuildable cache: losing
// it, or finding it truncated, version-mismatched, checksum-bad or
// contradictory to the segments, only triggers a full rebuild from the
// segment files — never data loss and never a user-visible error.
//
// Layout, all integers little-endian:
//
//	header  8 bytes  "BCLIDX" (6 bytes) + uint16 version
//	records          length-prefixed, checksummed, in (segment, offset)
//	                 order:
//
//	  committed entry ("E"):
//	    8 bytes segment file number
//	    8 bytes offset of the entry's segment magic
//	    8 bytes length of the whole entry on disk (magic ... crc)
//	    4 bytes disk entry CRC (the checksum stored by the segment)
//	    4 bytes member count m
//	    1 byte  flags (bit 0: entry uses keyed framing — BCLI/BCLK)
//	    m × (8-byte seq, 8-byte body offset, 4-byte body length,
//	         2-byte key length, key bytes; key length 0 = anonymous)
//
// Version 1 sidecars (no flags byte and no key fields) are not
// interpreted: a version mismatch triggers the ordinary one-time rebuild
// from the segment files, exactly like any other invalid sidecar.
//
//	hole marker ("H"):
//	  8 bytes segment file number
//	  8 bytes offset of the marker's segment magic
//	  8 bytes length of the whole marker on disk
//	  4 bytes disk marker CRC
//	  4 bytes sequence count c
//	  c × 8-byte sequence
//
// Every record is framed as: 1-byte type, 4-byte body length, body,
// 4-byte CRC32 of type+length+body. A torn final record — the remnant
// of a crash between the index write and its sync — is discarded on the
// next open, and any such truncation makes Open rebuild from the
// segments instead. Records are appended only after the corresponding
// segment entry is durable, so an adopted index can never advertise a
// batch the segments do not contain; adoption re-verifies the physical
// layout and every disk CRC before trusting it.
var (
	indexMagic   = []byte{'B', 'C', 'L', 'I', 'D', 'X'}
	indexVersion = uint16(2)

	recEntry = byte('E')
	recHole  = byte('H')

	// entryFlagKeyed marks an E record whose segment entry uses keyed
	// framing (BCLI for a lone keyed commit, BCLK for a group containing
	// at least one keyed member).
	entryFlagKeyed = byte(1)
)

// indexEntry is one committed segment entry: either a single batch or a
// whole group, located on disk and carrying every member's index ref.
type indexEntry struct {
	seg     int
	off     int // offset of the entry's segment magic
	length  int // total length of the entry on disk, including its CRC
	diskCRC uint32
	keyed   bool // segment entry is BCLI/BCLK rather than BCL1/BCLG
	members []indexMember
}

type indexMember struct {
	seq    uint64
	id     string // idempotency key, "" for an anonymous member
	off    int    // body offset within the segment file
	length int    // body length
}

// indexHole is one durable BCLH marker on disk.
type indexHole struct {
	seg     int
	off     int
	length  int
	diskCRC uint32
	seqs    []uint64
}

type parsedIndex struct {
	entries []indexEntry
	holes   []indexHole
}

var errIndexInvalid = errors.New("log: invalid index sidecar")

// readIndexFile parses the sidecar bytes strictly. A truncated final
// record — the remnant of a crash between an index write and its sync —
// is reported as tailLen (the valid prefix length). Missing tail bytes
// are the only tolerated defect; bad framing, an unknown version or any
// checksum mismatch yield errIndexInvalid.
func readIndexFile(data []byte) (p parsedIndex, tailLen int, err error) {
	const headerLen = 8
	if len(data) < headerLen {
		return parsedIndex{}, 0, errIndexInvalid
	}
	if string(data[:6]) != string(indexMagic) {
		return parsedIndex{}, 0, errIndexInvalid
	}
	if binary.LittleEndian.Uint16(data[6:8]) != indexVersion {
		return parsedIndex{}, 0, errIndexInvalid
	}
	pos := headerLen
	for pos < len(data) {
		start := pos
		rest := data[pos:]
		if len(rest) < 10 {
			// type(1) + length(4) + crc(4) is the smallest record.
			return p, start, nil
		}
		kind := rest[0]
		bodyLen := int(binary.LittleEndian.Uint32(rest[1:5]))
		if bodyLen < 0 {
			return parsedIndex{}, 0, errIndexInvalid
		}
		total := 5 + bodyLen + 4 // type + length + body + crc
		if len(data)-start < total {
			// Any truncation of the last record is a crash tail.
			return p, start, nil
		}
		body := rest[5 : 5+bodyLen]
		crc := binary.LittleEndian.Uint32(rest[5+bodyLen : 9+bodyLen])
		if crc32.ChecksumIEEE(rest[:5+bodyLen]) != crc {
			return parsedIndex{}, 0, errIndexInvalid
		}
		bp := 0
		switch kind {
		case recEntry:
			const fixed = 8 + 8 + 8 + 4 + 4 + 1
			if bodyLen < fixed {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e := indexEntry{}
			e.seg = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.off = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.length = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			e.diskCRC = binary.LittleEndian.Uint32(body[bp : bp+4])
			bp += 4
			m := int(binary.LittleEndian.Uint32(body[bp : bp+4]))
			bp += 4
			flags := body[bp]
			bp++
			if flags & ^entryFlagKeyed != 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e.keyed = flags&entryFlagKeyed != 0
			if m <= 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			e.members = make([]indexMember, m)
			for i := 0; i < m; i++ {
				if bodyLen-bp < 8+8+4+2 {
					return parsedIndex{}, 0, errIndexInvalid
				}
				mb := indexMember{
					seq:    binary.LittleEndian.Uint64(body[bp : bp+8]),
					off:    int(binary.LittleEndian.Uint64(body[bp+8 : bp+16])),
					length: int(binary.LittleEndian.Uint32(body[bp+16 : bp+20])),
				}
				bp += 20
				klen := int(binary.LittleEndian.Uint16(body[bp : bp+2]))
				bp += 2
				if !e.keyed && klen != 0 {
					return parsedIndex{}, 0, errIndexInvalid
				}
				if klen < 0 || klen > maxBatchIDLen || bodyLen-bp < klen {
					return parsedIndex{}, 0, errIndexInvalid
				}
				if klen > 0 {
					raw := body[bp : bp+klen]
					if bytes.IndexByte(raw, 0) >= 0 || !utf8.Valid(raw) {
						return parsedIndex{}, 0, errIndexInvalid
					}
					mb.id = string(raw)
					bp += klen
				}
				e.members[i] = mb
			}
			if bp != bodyLen {
				return parsedIndex{}, 0, errIndexInvalid
			}
			if e.seg <= 0 || e.off < 0 || e.length <= 0 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			p.entries = append(p.entries, e)
		case recHole:
			if bodyLen < 8+8+8+4+4 {
				return parsedIndex{}, 0, errIndexInvalid
			}
			h := indexHole{}
			h.seg = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.off = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.length = int(binary.LittleEndian.Uint64(body[bp : bp+8]))
			bp += 8
			h.diskCRC = binary.LittleEndian.Uint32(body[bp : bp+4])
			bp += 4
			c := int(binary.LittleEndian.Uint32(body[bp : bp+4]))
			bp += 4
			if h.seg <= 0 || h.off < 0 || h.length <= 0 || c < 0 || 8*c != bodyLen-bp {
				return parsedIndex{}, 0, errIndexInvalid
			}
			h.seqs = make([]uint64, c)
			for i := 0; i < c; i++ {
				h.seqs[i] = binary.LittleEndian.Uint64(body[bp : bp+8])
				bp += 8
			}
			p.holes = append(p.holes, h)
		default:
			return parsedIndex{}, 0, errIndexInvalid
		}
		pos = start + total
	}
	return p, 0, nil
}

// encodeIndexHeader returns the sidecar header.
func encodeIndexHeader() []byte {
	buf := make([]byte, 0, 8)
	buf = append(buf, indexMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint16(tmp[:2], indexVersion)
	return append(buf, tmp[:2]...)
}

// finishIndexRecord wraps a record body with its type tag, length and
// trailing checksum.
func finishIndexRecord(kind byte, body []byte) []byte {
	rec := make([]byte, 0, 5+len(body)+4)
	rec = append(rec, kind)
	var tmp [8]byte
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(body)))
	rec = append(rec, tmp[:4]...)
	rec = append(rec, body...)
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(rec))
	return append(rec, tmp[:4]...)
}

func putIndexU64(body *[]byte, tmp *[8]byte, v uint64) {
	binary.LittleEndian.PutUint64(tmp[:], v)
	*body = append(*body, tmp[:]...)
}

// encodeEntryRecord encodes one committed segment entry and its members.
func encodeEntryRecord(e indexEntry) []byte {
	size := 8 + 8 + 8 + 4 + 4 + 1
	for _, m := range e.members {
		size += 8 + 8 + 4 + 2 + len(m.id)
	}
	body := make([]byte, 0, size)
	var tmp [8]byte
	putIndexU64(&body, &tmp, uint64(e.seg))
	putIndexU64(&body, &tmp, uint64(e.off))
	putIndexU64(&body, &tmp, uint64(e.length))
	binary.LittleEndian.PutUint32(tmp[:4], e.diskCRC)
	body = append(body, tmp[:4]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(e.members)))
	body = append(body, tmp[:4]...)
	flags := byte(0)
	if e.keyed {
		flags = entryFlagKeyed
	}
	body = append(body, flags)
	for _, m := range e.members {
		putIndexU64(&body, &tmp, m.seq)
		putIndexU64(&body, &tmp, uint64(m.off))
		binary.LittleEndian.PutUint32(tmp[:4], uint32(m.length))
		body = append(body, tmp[:4]...)
		binary.LittleEndian.PutUint16(tmp[:2], uint16(len(m.id)))
		body = append(body, tmp[:2]...)
		body = append(body, m.id...)
	}
	return finishIndexRecord(recEntry, body)
}

// encodeHoleRecord encodes one durable hole marker as seen in a segment.
func encodeHoleRecord(h indexHole) []byte {
	body := make([]byte, 0, 8+8+8+4+4+8*len(h.seqs))
	var tmp [8]byte
	putIndexU64(&body, &tmp, uint64(h.seg))
	putIndexU64(&body, &tmp, uint64(h.off))
	putIndexU64(&body, &tmp, uint64(h.length))
	binary.LittleEndian.PutUint32(tmp[:4], h.diskCRC)
	body = append(body, tmp[:4]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(h.seqs)))
	body = append(body, tmp[:4]...)
	for _, seq := range h.seqs {
		putIndexU64(&body, &tmp, seq)
	}
	return finishIndexRecord(recHole, body)
}

// diskRecord is one physical on-disk item located by the index, merged
// in (segment, offset) order for the canonical snapshot.
type diskRecord struct {
	seg int
	off int
	enc []byte
}

// writeIndexSnapshot replaces the sidecar atomically with a full image
// of the recovered log: the header, then every committed entry and hole
// marker in (segment, offset) order. The temp file is fsynced before
// the rename; callers run this after the segment bytes it describes are
// synced. A lost rename only leaves the previous sidecar behind, which
// adoption validation rejects as contradictory, triggering a rebuild.
func (l *Log) writeIndexSnapshot(p parsedIndex) error {
	var recs []diskRecord
	for i := range p.entries {
		e := &p.entries[i]
		recs = append(recs, diskRecord{seg: e.seg, off: e.off, enc: encodeEntryRecord(*e)})
	}
	for i := range p.holes {
		h := &p.holes[i]
		recs = append(recs, diskRecord{seg: h.seg, off: h.off, enc: encodeHoleRecord(*h)})
	}
	sort.SliceStable(recs, func(i, j int) bool {
		if recs[i].seg != recs[j].seg {
			return recs[i].seg < recs[j].seg
		}
		return recs[i].off < recs[j].off
	})
	var buf []byte
	buf = append(buf, encodeIndexHeader()...)
	for _, r := range recs {
		buf = append(buf, r.enc...)
	}
	tmp := l.indexPath() + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(buf); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		os.Remove(tmp)
		return err
	}
	if err := f.Close(); err != nil {
		os.Remove(tmp)
		return err
	}
	if err := os.Rename(tmp, l.indexPath()); err != nil {
		os.Remove(tmp)
		return err
	}
	// Best effort: if the rename is not journaled and power loss keeps
	// the previous sidecar, adoption validation detects the divergence
	// and rebuilds, so snapshot correctness never depends on this sync.
	_ = syncDir(l.dir)
	return nil
}

// appendIndexRecord appends one record to the live sidecar after a
// commit's segment entry is durable. With Options.Sync it fsyncs the
// sidecar before returning. Any failure is returned to the caller,
// which rolls the just-written segment entry and this record back; an
// fsync failure is wrapped as ErrSyncFailed so commits keep their
// documented error semantics.
func (l *Log) appendIndexRecord(rec []byte) error {
	if l.idxFile == nil {
		return errIndexInvalid
	}
	if _, err := l.idxFile.Write(rec); err != nil {
		return err
	}
	l.idxSize += len(rec)
	if l.opts.Sync {
		if err := syncFile(l.idxFile); err != nil {
			return fmt.Errorf("%w: %v", ErrSyncFailed, err)
		}
	}
	return nil
}

// truncateIndex rolls the sidecar back to size n after a failed commit,
// mirroring the segment-entry rollback so no uncommitted record is left
// behind and a retry cannot duplicate it.
func (l *Log) truncateIndex(n int) {
	if l.idxFile == nil {
		return
	}
	if err := l.idxFile.Truncate(int64(n)); err != nil {
		// Best effort: an untidy sidecar is harmless. Open never trusts
		// it blindly and rebuilds from the segments on any contradiction.
		return
	}
	l.idxSize = n
}

// openIndex opens the live sidecar for append, creating it absent. The
// file has already been validated (or freshly snapshotted) by Open; an
// empty file (a log with no commits yet) gets its header first.
func (l *Log) openIndex() error {
	f, err := os.OpenFile(l.indexPath(), os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o644)
	if err != nil {
		return err
	}
	st, err := f.Stat()
	if err != nil {
		f.Close()
		return err
	}
	l.idxFile = f
	l.idxSize = int(st.Size())
	if l.idxSize == 0 {
		hdr := encodeIndexHeader()
		if _, err := f.Write(hdr); err != nil {
			f.Close()
			l.idxFile = nil
			return err
		}
		l.idxSize = len(hdr)
	}
	return nil
}

// readIndexBytes reads the whole sidecar. Used only by adoption.
func (l *Log) readIndexBytes() ([]byte, error) {
	f, err := os.Open(l.indexPath())
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return io.ReadAll(f)
}

package log

import (
	"bytes"
	"encoding/binary"
	"hash/crc32"
	"unicode/utf8"
)

// On-disk entry layouts, all integers little-endian. A segment file is a
// sequence of entries of three kinds:
//
// Single batch, written by Commit ("BCL1"):
//
//	magic   4 bytes  "BCL1"
//	seq     8 bytes  batch sequence number
//	count   4 bytes  number of records
//	records count × (4-byte length + opaque bytes)
//	crc32   4 bytes  IEEE checksum of everything before it
//
// Batch group, written by CommitGroup as one atomic unit ("BCLG"):
//
//	magic   4 bytes  "BCLG"
//	count   4 bytes  number of batches in the group
//	batches count × (8-byte seq + 4-byte record count + records)
//	crc32   4 bytes  IEEE checksum of everything before it
//
// Keyed single batch, written by Commit for a batch from AppendIdempotent
// ("BCLI"): identical to BCL1 with one extra field — a length-prefixed
// idempotency key between the sequence and the record count:
//
//	magic   4 bytes  "BCLI"
//	seq     8 bytes  batch sequence number
//	keyLen  2 bytes  length of the idempotency key
//	key     keyLen bytes
//	count   4 bytes  number of records
//	records count × (4-byte length + opaque bytes)
//	crc32   4 bytes  IEEE checksum of everything before it
//
// The indexed body starts at seq (right after the magic), so it reads
// seq + keyLen + key + count + records.
//
// Keyed batch group, written by CommitGroup when at least one member was
// staged with AppendIdempotent ("BCLK"). Each member is the BCLG member
// layout with a length-prefixed key inserted right after its seq; key
// length 0 marks an anonymous member:
//
//	magic   4 bytes  "BCLK"
//	count   4 bytes  number of batches in the group
//	batches count × (8-byte seq + 2-byte key length + key
//	                + 4-byte record count + records)
//	crc32   4 bytes  IEEE checksum of everything before it
//
// Hole marker, written by crash recovery to make the sequences reserved
// by a torn tail permanent ("BCLH"):
//
//	magic   4 bytes  "BCLH"
//	count   4 bytes  number of reserved sequences
//	seqs    count × 8 bytes
//	crc32   4 bytes  IEEE checksum of everything before it
//
// The trailing checksum makes tampering detectable as ErrCorruptSegment
// when the segment is parsed. A torn write left by a crash is instead
// reported as a tail: a strict prefix of a valid entry, never a full
// entry with a bad checksum. A group entry is durable only as a whole —
// a truncated group is a tail and none of its batches become visible.
// The keyed encodings exist only for keyed batches: anonymous traffic
// keeps using BCL1/BCLG byte for byte, and recovery never invents a key
// for an anonymous batch.
var (
	segmentMagic = []byte{'B', 'C', 'L', '1'}
	groupMagic   = []byte{'B', 'C', 'L', 'G'}
	holeMagic    = []byte{'B', 'C', 'L', 'H'}
	keyedMagic   = []byte{'B', 'C', 'L', 'I'}
	keyedGroup   = []byte{'B', 'C', 'L', 'K'}
)

const (
	entryHeaderLen = 4 + 8 + 4
	// maxBatchIDLen bounds an idempotency key on disk; AppendIdempotent
	// rejects longer keys before they reach the encoder.
	maxBatchIDLen = 256
)

// groupMember is one staged batch inside a group commit. A non-empty id
// marks a member staged with AppendIdempotent.
type groupMember struct {
	seq     uint64
	id      string
	records [][]byte
}

func encodeBatch(seq uint64, records [][]byte) []byte {
	size := entryHeaderLen + 4
	for _, r := range records {
		size += 4 + len(r)
	}
	buf := make([]byte, 0, size)
	buf = append(buf, segmentMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint64(tmp[:], seq)
	buf = append(buf, tmp[:]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(records)))
	buf = append(buf, tmp[:4]...)
	appendRecords(&buf, &tmp, records)
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
	return append(buf, tmp[:4]...)
}

// encodeKeyedBatch encodes a single batch carrying an idempotency key
// (BCLI). The layout matches encodeBatch apart from the length-prefixed
// key between the sequence and the record count.
func encodeKeyedBatch(seq uint64, id string, records [][]byte) []byte {
	size := 4 + 8 + 2 + len(id) + 4 + 4
	for _, r := range records {
		size += 4 + len(r)
	}
	buf := make([]byte, 0, size)
	buf = append(buf, keyedMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint64(tmp[:], seq)
	buf = append(buf, tmp[:]...)
	binary.LittleEndian.PutUint16(tmp[:2], uint16(len(id)))
	buf = append(buf, tmp[:2]...)
	buf = append(buf, id...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(records)))
	buf = append(buf, tmp[:4]...)
	appendRecords(&buf, &tmp, records)
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
	return append(buf, tmp[:4]...)
}

// appendRecords appends count records as (4-byte length + opaque bytes).
func appendRecords(buf *[]byte, tmp *[8]byte, records [][]byte) {
	for _, r := range records {
		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(r)))
		*buf = append(*buf, tmp[:4]...)
		*buf = append(*buf, r...)
	}
}

// encodeGroup encodes a batch group as a single entry. It uses BCLK and
// key-framed members whenever at least one member carries a key, so a
// mixed anonymous/keyed group is one atomic entry; a fully anonymous
// group keeps the historical BCLG encoding byte for byte. It also
// returns, for each member, the offset and length of its decodable body
// relative to the start of the entry, so the index can point straight at
// one member of the group. A keyed member's body begins at its key
// length prefix; an anonymous BCLG member's body begins at its seq.
func encodeGroup(members []groupMember) (entry []byte, offs []int, lens []int) {
	for _, m := range members {
		if m.id != "" {
			return encodeKeyedGroup(members)
		}
	}
	return encodeAnonGroup(members)
}

// encodeAnonGroup encodes a fully anonymous group with the historical
// BCLG layout; each member body is seq + record count + records.
func encodeAnonGroup(members []groupMember) (entry []byte, offs []int, lens []int) {
	size := 4 + 4 + 4
	for _, m := range members {
		size += 8 + 4
		for _, r := range m.records {
			size += 4 + len(r)
		}
	}
	buf := make([]byte, 0, size)
	buf = append(buf, groupMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(members)))
	buf = append(buf, tmp[:4]...)
	offs = make([]int, len(members))
	lens = make([]int, len(members))
	for i, m := range members {
		offs[i] = len(buf)
		binary.LittleEndian.PutUint64(tmp[:], m.seq)
		buf = append(buf, tmp[:]...)
		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(m.records)))
		buf = append(buf, tmp[:4]...)
		appendRecords(&buf, &tmp, m.records)
		lens[i] = len(buf) - offs[i]
	}
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
	return append(buf, tmp[:4]...), offs, lens
}

// encodeKeyedGroup encodes a group with at least one keyed member as a
// single BCLK entry. Each member body (whose span is returned for the
// index) is: seq + 2-byte key length + key + record count + records; an
// anonymous member's key length is zero.
func encodeKeyedGroup(members []groupMember) (entry []byte, offs []int, lens []int) {
	size := 4 + 4 + 4
	for _, m := range members {
		size += 8 + 2 + len(m.id) + 4
		for _, r := range m.records {
			size += 4 + len(r)
		}
	}
	buf := make([]byte, 0, size)
	buf = append(buf, keyedGroup...)
	var tmp [8]byte
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(members)))
	buf = append(buf, tmp[:4]...)
	offs = make([]int, len(members))
	lens = make([]int, len(members))
	for i, m := range members {
		offs[i] = len(buf)
		binary.LittleEndian.PutUint64(tmp[:], m.seq)
		buf = append(buf, tmp[:]...)
		binary.LittleEndian.PutUint16(tmp[:2], uint16(len(m.id)))
		buf = append(buf, tmp[:2]...)
		buf = append(buf, m.id...)
		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(m.records)))
		buf = append(buf, tmp[:4]...)
		appendRecords(&buf, &tmp, m.records)
		lens[i] = len(buf) - offs[i]
	}
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
	return append(buf, tmp[:4]...), offs, lens
}

// encodeHoles encodes a hole marker reserving the given sequences
// forever. Recovery writes it in place of a torn tail so the reserved
// sequences survive as permanent holes across reopens.
func encodeHoles(seqs []uint64) []byte {
	buf := make([]byte, 0, 4+4+8*len(seqs)+4)
	buf = append(buf, holeMagic...)
	var tmp [8]byte
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(seqs)))
	buf = append(buf, tmp[:4]...)
	for _, seq := range seqs {
		binary.LittleEndian.PutUint64(tmp[:], seq)
		buf = append(buf, tmp[:]...)
	}
	binary.LittleEndian.PutUint32(tmp[:4], crc32.ChecksumIEEE(buf))
	return append(buf, tmp[:4]...)
}

// decodeBody decodes one anonymous batch body (seq + record count +
// records) as located by the index. Unlike segment parsing, any
// inconsistency here is corruption: an indexed body was validated when
// the segment was parsed, so a mismatch means the file changed
// underneath the log.
func decodeBody(body []byte) (uint64, [][]byte, error) {
	if len(body) < 12 {
		return 0, nil, ErrCorruptSegment
	}
	seq := binary.LittleEndian.Uint64(body[:8])
	count := binary.LittleEndian.Uint32(body[8:12])
	records, pos, ok := parseRecords(body, 12, count)
	if !ok || pos != len(body) {
		return 0, nil, ErrCorruptSegment
	}
	return seq, records, nil
}

// decodeKeyedBody decodes one keyed-framed body as located by the
// index. BCLI and BCLK member bodies share one shape: seq, then a
// 2-byte length-prefixed key, then the record count and records. A zero
// key length yields id == "" for an anonymous member of a BCLK group;
// readRef only reaches this decoder for keyed-framed refs. Any framing
// defect is corruption: the encoder only ever writes valid frames.
func decodeKeyedBody(body []byte) (uint64, string, [][]byte, error) {
	if len(body) < 8 {
		return 0, "", nil, ErrCorruptSegment
	}
	seq := binary.LittleEndian.Uint64(body[:8])
	id, n, ok, bad := parseKey(body, 8)
	if bad || !ok || len(body)-n < 4 {
		return 0, "", nil, ErrCorruptSegment
	}
	count := binary.LittleEndian.Uint32(body[n : n+4])
	records, pos, ok := parseRecords(body, n+4, count)
	if !ok || pos != len(body) {
		return 0, "", nil, ErrCorruptSegment
	}
	return seq, id, records, nil
}

// parseKey reads a 2-byte length-prefixed key from body at pos. A zero
// length is framing-valid and returns an empty id (an anonymous member
// of a BCLK group); callers that require a key (BCLI) reject that
// themselves. ok is false when the declared key does not fit (a torn
// write). A present but malformed key (length over 256, NUL byte or
// invalid UTF-8) is reported as bad=true: a torn write cannot produce
// whole-but-invalid key bytes, so callers treat it as ErrCorruptSegment
// rather than a tail.
func parseKey(body []byte, pos int) (id string, npos int, ok, bad bool) {
	if len(body)-pos < 2 {
		return "", 0, false, false
	}
	n := int(binary.LittleEndian.Uint16(body[pos : pos+2]))
	if n > maxBatchIDLen {
		return "", 0, false, true
	}
	end := pos + 2 + n
	if len(body) < end {
		return "", 0, false, false
	}
	if n == 0 {
		return "", end, true, false
	}
	raw := body[pos+2 : end]
	if bytes.IndexByte(raw, 0) >= 0 || !utf8.Valid(raw) {
		return "", 0, false, true
	}
	return string(raw), end, true, false
}

type parsedBatch struct {
	seq     uint64
	id      string // idempotency key, empty for an anonymous batch
	records [][]byte
	off     int // offset of the batch body within the segment
	length  int // length of the batch body
	// keyed reports the entry framing: true for BCLI and every BCLK
	// member (whose body starts with a key length prefix), false for
	// BCL1/BCLG. An anonymous member of a mixed BCLK group is keyed.
	keyed bool
	// diskOff/diskLen/diskCRC describe the whole entry on disk (magic
	// through trailing checksum) and the checksum it stores. The index
	// sidecar records them so adoption can re-verify an entry against
	// the segment without decoding any of its records.
	diskOff int
	diskLen int
	diskCRC uint32
}

type parsedHole struct {
	off    int // offset of the marker's magic within the segment
	length int // total length of the marker on disk, including its CRC
	crc    uint32
	seqs   []uint64
}

// segmentTail describes an incomplete entry at the end of a segment: the
// remnant of a crash in the middle of a write.
type segmentTail struct {
	off  int      // offset where the incomplete entry starts
	seqs []uint64 // sequences the torn entry had already reserved
}

// parseSegment decodes every complete entry in data, returning the
// committed batches (with the offsets of their bodies, for the index)
// and the durable hole markers. A truncated tail — trailing bytes that
// are only a prefix of an entry — is reported separately as the
// signature of a crash mid-write, along with every sequence the torn
// entry had already reserved. Any other inconsistency (unknown magic,
// bad checksum) yields ErrCorruptSegment.
func parseSegment(data []byte) ([]parsedBatch, []parsedHole, *segmentTail, error) {
	var batches []parsedBatch
	var holes []parsedHole
	var off int
	for off < len(data) {
		rest := data[off:]
		if len(rest) < len(segmentMagic) {
			// A partial magic is a torn write only if it is a
			// prefix of a valid magic; all magics share "BCL".
			if !bytes.Equal(rest, segmentMagic[:len(rest)]) {
				return nil, nil, nil, ErrCorruptSegment
			}
			return batches, holes, &segmentTail{off: off}, nil
		}
		switch {
		case bytes.Equal(rest[:4], segmentMagic):
			if len(rest) < entryHeaderLen {
				tail := &segmentTail{off: off}
				if len(rest) >= 12 {
					tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(rest[4:12]))
				}
				return batches, holes, tail, nil
			}
			seq := binary.LittleEndian.Uint64(rest[4:12])
			count := binary.LittleEndian.Uint32(rest[12:16])
			pos := off + entryHeaderLen
			records, npos, ok := parseRecords(data, pos, count)
			if !ok {
				return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
			}
			pos = npos
			if len(data)-pos < 4 {
				return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[off:pos]) != crc {
				return nil, nil, nil, ErrCorruptSegment
			}
			batches = append(batches, parsedBatch{
				seq: seq, records: records,
				off: off + 4, length: pos - off - 4,
				diskOff: off, diskLen: pos + 4 - off, diskCRC: crc,
			})
			off = pos + 4
		case bytes.Equal(rest[:4], keyedMagic):
			// BCLI: magic + seq + 2-byte key length + key + count +
			// records + crc. The indexed body starts at seq (right
			// after the magic); decodeKeyedBody consumes it on reads.
			if len(rest) < entryHeaderLen {
				tail := &segmentTail{off: off}
				if len(rest) >= 12 {
					tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(rest[4:12]))
				}
				return batches, holes, tail, nil
			}
			seq := binary.LittleEndian.Uint64(rest[4:12])
			id, kpos, ok, bad := parseKey(data, off+12)
			if bad {
				return nil, nil, nil, ErrCorruptSegment
			}
			if !ok {
				return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
			}
			if id == "" {
				// BCLI always carries a key; a key-less one is tampering.
				return nil, nil, nil, ErrCorruptSegment
			}
			if len(data)-kpos < 4 {
				return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
			}
			count := binary.LittleEndian.Uint32(data[kpos : kpos+4])
			records, npos, ok := parseRecords(data, kpos+4, count)
			if !ok {
				return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
			}
			pos := npos
			if len(data)-pos < 4 {
				return batches, holes, &segmentTail{off: off, seqs: []uint64{seq}}, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[off:pos]) != crc {
				return nil, nil, nil, ErrCorruptSegment
			}
			batches = append(batches, parsedBatch{
				seq: seq, id: id, records: records, keyed: true,
				off: off + 4, length: pos - off - 4,
				diskOff: off, diskLen: pos + 4 - off, diskCRC: crc,
			})
			off = pos + 4
		case bytes.Equal(rest[:4], groupMagic):
			tail := &segmentTail{off: off}
			if len(rest) < 8 {
				return batches, holes, tail, nil
			}
			count := binary.LittleEndian.Uint32(rest[4:8])
			pos := off + 8
			var members []parsedBatch
			for i := uint32(0); i < count; i++ {
				if len(data)-pos < 12 {
					// Torn between or inside member headers;
					// recover the member's sequence if whole.
					if len(data)-pos >= 8 {
						tail.seqs = append(tail.seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
					}
					return batches, holes, tail, nil
				}
				mOff := pos
				seq := binary.LittleEndian.Uint64(data[pos : pos+8])
				nrec := binary.LittleEndian.Uint32(data[pos+8 : pos+12])
				tail.seqs = append(tail.seqs, seq)
				records, npos, ok := parseRecords(data, pos+12, nrec)
				if !ok {
					return batches, holes, tail, nil
				}
				pos = npos
				members = append(members, parsedBatch{seq: seq, records: records, off: mOff, length: pos - mOff})
			}
			if len(data)-pos < 4 {
				return batches, holes, tail, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[off:pos]) != crc {
				return nil, nil, nil, ErrCorruptSegment
			}
			// Only a complete, checksummed group publishes its
			// members; a torn group above publishes none.
			for _, mb := range members {
				mb.diskOff, mb.diskLen, mb.diskCRC = off, pos+4-off, crc
				batches = append(batches, mb)
			}
			off = pos + 4
		case bytes.Equal(rest[:4], keyedGroup):
			// BCLK: count members, each framed as seq + 2-byte key
			// length + key + record count + records. Key length 0 marks
			// an anonymous member of a mixed group.
			tail := &segmentTail{off: off}
			if len(rest) < 8 {
				return batches, holes, tail, nil
			}
			count := binary.LittleEndian.Uint32(rest[4:8])
			pos := off + 8
			var members []parsedBatch
			for i := uint32(0); i < count; i++ {
				if len(data)-pos < 8 {
					// Torn before the member's sequence: no sequence to
					// reserve a hole for.
					return batches, holes, tail, nil
				}
				mOff := pos
				seq := binary.LittleEndian.Uint64(data[pos : pos+8])
				tail.seqs = append(tail.seqs, seq)
				id, kpos, ok, bad := parseKey(data, pos+8)
				if bad {
					return nil, nil, nil, ErrCorruptSegment
				}
				if !ok {
					// Missing key-length bytes or a key cut short: torn.
					return batches, holes, tail, nil
				}
				pos = kpos
				if len(data)-pos < 4 {
					return batches, holes, tail, nil
				}
				nrec := binary.LittleEndian.Uint32(data[pos : pos+4])
				records, npos, ok := parseRecords(data, pos+4, nrec)
				if !ok {
					return batches, holes, tail, nil
				}
				pos = npos
				members = append(members, parsedBatch{
					seq: seq, id: id, records: records, keyed: true,
					off: mOff, length: pos - mOff,
				})
			}
			if len(data)-pos < 4 {
				return batches, holes, tail, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[off:pos]) != crc {
				return nil, nil, nil, ErrCorruptSegment
			}
			for _, mb := range members {
				mb.diskOff, mb.diskLen, mb.diskCRC = off, pos+4-off, crc
				mb.keyed = true
				batches = append(batches, mb)
			}
			off = pos + 4
		case bytes.Equal(rest[:4], holeMagic):
			tail := &segmentTail{off: off}
			if len(rest) < 8 {
				return batches, holes, tail, nil
			}
			count := binary.LittleEndian.Uint32(rest[4:8])
			pos := off + 8
			var seqs []uint64
			for i := uint32(0); i < count; i++ {
				if len(data)-pos < 8 {
					tail.seqs = append(tail.seqs, seqs...)
					return batches, holes, tail, nil
				}
				seqs = append(seqs, binary.LittleEndian.Uint64(data[pos:pos+8]))
				pos += 8
			}
			if len(data)-pos < 4 {
				tail.seqs = append(tail.seqs, seqs...)
				return batches, holes, tail, nil
			}
			crc := binary.LittleEndian.Uint32(data[pos : pos+4])
			if crc32.ChecksumIEEE(data[off:pos]) != crc {
				return nil, nil, nil, ErrCorruptSegment
			}
			holes = append(holes, parsedHole{
				off: off, length: pos + 4 - off, crc: crc,
				seqs: append(make([]uint64, 0, len(seqs)), seqs...),
			})
			off = pos + 4
		default:
			return nil, nil, nil, ErrCorruptSegment
		}
	}
	return batches, holes, nil, nil
}

// parseRecords decodes count records starting at pos. ok is false when
// the data runs out first, which callers read as a torn write.
func parseRecords(data []byte, pos int, count uint32) (records [][]byte, npos int, ok bool) {
	records = make([][]byte, 0, min(int(count), 1<<20))
	for i := uint32(0); i < count; i++ {
		if len(data)-pos < 4 {
			return nil, 0, false
		}
		n := int(binary.LittleEndian.Uint32(data[pos : pos+4]))
		pos += 4
		if n < 0 || len(data)-pos < n {
			return nil, 0, false
		}
		rec := make([]byte, n)
		copy(rec, data[pos:pos+n])
		pos += n
		records = append(records, rec)
	}
	return records, pos, true
}

// Command logctl inspects a batch-commit log directory.
//
//	logctl --dir <path> stat
//
// stat prints one compact JSON line summarising the directory:
//
//	{"segments":2,"firstSeq":1,"lastSeq":7}
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"

	bcl "github.com/Hulalalalalalalalalalala/batch-commit-log"
)

func main() {
	fs := flag.NewFlagSet("logctl", flag.ExitOnError)
	dir := fs.String("dir", "", "path to the log directory")
	fs.Parse(os.Args[1:])
	if *dir == "" || fs.NArg() != 1 || fs.Arg(0) != "stat" {
		fmt.Fprintln(os.Stderr, "usage: logctl --dir <path> stat")
		os.Exit(2)
	}

	l, err := bcl.Open(*dir, bcl.Options{SegmentBytes: 64 << 20})
	if err != nil {
		fmt.Fprintln(os.Stderr, "logctl:", err)
		os.Exit(1)
	}
	defer l.Close()

	segs := l.Segments()
	var first, last uint64
	for i, s := range segs {
		if i == 0 || s.FirstSeq < first {
			first = s.FirstSeq
		}
		if i == 0 || s.LastSeq > last {
			last = s.LastSeq
		}
	}
	out := struct {
		Segments int    `json:"segments"`
		FirstSeq uint64 `json:"firstSeq"`
		LastSeq  uint64 `json:"lastSeq"`
	}{Segments: len(segs), FirstSeq: first, LastSeq: last}
	line, err := json.Marshal(out)
	if err != nil {
		fmt.Fprintln(os.Stderr, "logctl:", err)
		os.Exit(1)
	}
	fmt.Println(string(line))
}

