30			if err != nil {
31				t.Fatalf("Append: %v", err)
32			}
33			gs = append(gs, b)
34		}
35		if _, err := l.CommitGroup(gs); err != nil {
36			t.Fatalf("CommitGroup: %v", err)
37		}
