49	func assertSeedState(t *testing.T, l *log.Log) {
50		t.Helper()
51		want := map[uint64][][]byte{
52			1: {[]byte("one")},
53			2: {[]byte("two"), []byte("three")},
54			3: {[]byte("g1")},
55			4: {[]byte("g2")},
