59			got, err := l.Read(seq)
60			if err != nil || !reflect.DeepEqual(got, recs) {
61				t.Fatalf("Read(%d) = %q, %v; want %q", seq, got, err, recs)
62			}
63		}
64		var seqs []uint64
65		if err := l.Scan(1, func(b log.Batch) error {
66			seqs = append(seqs, b.Seq())
67			return nil
68		}); err != nil {
