79		if segs[len(segs)-1].LastSeq != 5 {
80			t.Fatalf("last segment = %+v, want LastSeq 5", segs[len(segs)-1])
81		}
82		// Sorted by file order, non-overlapping ranges.
83		var prev uint64
84		for i, s := range segs {
85			if i > 0 && s.FirstSeq <= prev {
86				t.Fatalf("segments out of order: %+v", segs)
