176		// One committed batch per segment, then drop the last segment's
177		// bytes while the sidecar still claims the batch: adoption must
178		// reject the contradiction and rebuild must expose exactly what the
179		// segments hold — never the indexed-but-missing batch 1.
180		dir2 := t.TempDir()
