231	// appendCompleteEntry appends a valid, checksummed single-batch entry
232	// for seq with one record, simulating a crash after the segment entry
233	// is durable but before its index record lands.
234	func appendCompleteEntry(t *testing.T, path string, seq uint64, payload string) {
235		t.Helper()
236		var entry []byte
237		entry = append(entry, 'B', 'C', 'L', '1')
238		var tmp [8]byte
239		binary.LittleEndian.PutUint64(tmp[:], seq)
240		entry = append(entry, tmp[:]...)
241		binary.LittleEndian.PutUint32(tmp[:4], 1)
242		entry = append(entry, tmp[:4]...)
243		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(payload)))
244		entry = append(entry, tmp[:4]...)
245		entry = append(entry, payload...)
246		var crc [4]byte
247		binary.LittleEndian.PutUint32(crc[:], crc32.ChecksumIEEE(entry))
248		entry = append(entry, crc[:]...)
249		f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
250		if err != nil {
251			t.Fatal(err)
252		}
253		if _, err := f.Write(entry); err != nil {
254			t.Fatal(err)
255		}
256		if err := f.Close(); err != nil {
257			t.Fatal(err)
258		}
259	}
