17	func TestAppendIdempotentStagedReturnsSameBatch(t *testing.T) {
18		l := open(t, t.TempDir(), log.Options{SegmentBytes: 1 << 20})
19	
20		recs := [][]byte{[]byte("alpha"), []byte("beta")}
21		b1, err := l.AppendIdempotent("key-1", recs)
22		if err != nil {
23			t.Fatalf("AppendIdempotent: %v", err)
24		}
25		if b1.Seq() != 1 || b1.ID() != "key-1" {
26			t.Fatalf("first batch = seq %d id %q, want 1/key-1", b1.Seq(), b1.ID())
27		}
28		// A repeat before commit returns the very same staged batch and Seq,
29		// reserving nothing new.
30		b2, err := l.AppendIdempotent("key-1", recs)
31		if err != nil {
32			t.Fatalf("retry AppendIdempotent: %v", err)
33		}
34		if b2.Seq() != b1.Seq() || b2.ID() != b1.ID() {
35			t.Fatalf("retry batch = %d/%q, want same as %d/%q", b2.Seq(), b2.ID(), b1.Seq(), b1.ID())
36		}
37		if !reflect.DeepEqual(b2.Records(), recs) {
38			t.Fatalf("retry records = %q, want %q", b2.Records(), recs)
39		}
40		// A concurrent anonymous append shows the retry reserved no sequence.
41		anon, err := l.Append([][]byte{[]byte("anon")})
42		if err != nil {
43			t.Fatalf("Append: %v", err)
44		}
45		if anon.Seq() != 2 {
