294	// appendKeyedCompleteEntry appends a valid, checksummed BCLI entry for
295	// seq with key and one record, simulating a crash after the segment
296	// entry is durable but before its index record lands.
297	func appendKeyedCompleteEntry(t *testing.T, path string, seq uint64, key, payload string) {
298		t.Helper()
299		var entry []byte
300		entry = append(entry, 'B', 'C', 'L', 'I')
301		var tmp [8]byte
302		binary.LittleEndian.PutUint64(tmp[:], seq)
303		entry = append(entry, tmp[:]...)
304		binary.LittleEndian.PutUint16(tmp[:2], uint16(len(key)))
305		entry = append(entry, tmp[:2]...)
306		entry = append(entry, key...)
307		binary.LittleEndian.PutUint32(tmp[:4], 1)
308		entry = append(entry, tmp[:4]...)
309		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(payload)))
310		entry = append(entry, tmp[:4]...)
311		entry = append(entry, payload...)
312		var crc [4]byte
313		binary.LittleEndian.PutUint32(crc[:], crc32.ChecksumIEEE(entry))
314		entry = append(entry, crc[:]...)
315		if err := os.WriteFile(path, append(mustReadFile(t, path), entry...), 0o644); err != nil {
316			t.Fatal(err)
317		}
318	}
