451	// appendTornKeyedGroup writes a half-finished BCLK entry: an anonymous
452	// member and a keyed member are complete, the final keyed member is cut
453	// off mid-record and the checksum is missing.
454	func appendTornKeyedGroup(t *testing.T, dir string, finalSeq uint64, finalKey string) {
455		t.Helper()
456		files, err := filepath.Glob(filepath.Join(dir, "*.seg"))
457		if err != nil || len(files) == 0 {
458			t.Fatalf("segment files = %v, %v", files, err)
459		}
460		last := files[len(files)-1]
461		var entry []byte
462		entry = append(entry, 'B', 'C', 'L', 'K')
463		var tmp [8]byte
464		binary.LittleEndian.PutUint32(tmp[:4], 3) // three members
465		entry = append(entry, tmp[:4]...)
466		// Complete anonymous member with seq 2.
467		binary.LittleEndian.PutUint64(tmp[:], 2)
468		entry = append(entry, tmp[:]...)
469		binary.LittleEndian.PutUint16(tmp[:2], 0)
470		entry = append(entry, tmp[:2]...)
471		binary.LittleEndian.PutUint32(tmp[:4], 1)
472		entry = append(entry, tmp[:4]...)
473		binary.LittleEndian.PutUint32(tmp[:4], 2)
474		entry = append(entry, tmp[:4]...)
475		entry = append(entry, 'x', 'y')
476		// Complete keyed member with seq 3 and key "gk-1".
477		binary.LittleEndian.PutUint64(tmp[:], 3)
478		entry = append(entry, tmp[:]...)
479		binary.LittleEndian.PutUint16(tmp[:2], uint16(len("gk-1")))
480		entry = append(entry, tmp[:2]...)
481		entry = append(entry, "gk-1"...)
482		binary.LittleEndian.PutUint32(tmp[:4], 1)
483		entry = append(entry, tmp[:4]...)
484		binary.LittleEndian.PutUint32(tmp[:4], 2)
485		entry = append(entry, tmp[:4]...)
486		entry = append(entry, 'o', 'k')
487		// Final keyed member: header complete, record declared 100 bytes but
488		// only a prefix present, no checksum.
489		binary.LittleEndian.PutUint64(tmp[:], finalSeq)
490		entry = append(entry, tmp[:]...)
491		binary.LittleEndian.PutUint16(tmp[:2], uint16(len(finalKey)))
492		entry = append(entry, tmp[:2]...)
493		entry = append(entry, finalKey...)
494		binary.LittleEndian.PutUint32(tmp[:4], 1)
495		entry = append(entry, tmp[:4]...)
496		binary.LittleEndian.PutUint32(tmp[:4], 100)
497		entry = append(entry, tmp[:4]...)
498		entry = append(entry, []byte("only-a-prefix")...)
499		f, err := os.OpenFile(last, os.O_WRONLY|os.O_APPEND, 0)
500		if err != nil {
501			t.Fatal(err)
502		}
503		if _, err := f.Write(entry); err != nil {
504			t.Fatal(err)
505		}
506		if err := f.Close(); err != nil {
507			t.Fatal(err)
508		}
509	}
