536		b2, err := l.AppendIdempotent("gk-2", [][]byte{[]byte("b")})
537		if err != nil {
538			t.Fatalf("retry gk-2: %v", err)
539		}
540		if b2.Seq() != 6 {
541			t.Fatalf("gk-2 retry seq = %d, want 6", b2.Seq())
542		}
543	}
544	
545	func TestKeyedBatchesAcrossSegments(t *testing.T) {
546		dir := t.TempDir()
547		l := open(t, dir, log.Options{SegmentBytes: 48})
548	
549		var keys []string
550		for i := 0; i < 4; i++ {
551			key := "key-" + string(rune('a'+i))
552			b, err := l.AppendIdempotent(key, [][]byte{[]byte("payload-" + string(rune('a'+i)))})
553			if err != nil {
554				t.Fatalf("AppendIdempotent: %v", err)
555			}
556			if _, err := l.Commit(b); err != nil {
557				t.Fatalf("Commit: %v", err)
558			}
559			keys = append(keys, key)
560		}
561		l.Close()
562	
563		l = open(t, dir, log.Options{SegmentBytes: 48})
564		defer l.Close()
565		for i, key := range keys {
566			want := []byte("payload-" + string(rune('a'+i)))
567			b, err := l.AppendIdempotent(key, [][]byte{want})
568			if err != nil {
569				t.Fatalf("dedup %q: %v", key, err)
570			}
571			if b.Seq() != uint64(i+1) {
572				t.Fatalf("dedup %q seq = %d, want %d", key, b.Seq(), i+1)
573			}
574		}
575	}
576	
577	// seedKeyedLog writes single keyed, anonymous and mixed-group keyed
578	// batches, returning a dir whose every key must survive a rebuild.
579	func seedKeyedLog(t *testing.T) string {
580		t.Helper()
581		dir := t.TempDir()
582		l := open(t, dir, log.Options{SegmentBytes: 1 << 20, Sync: true})
583		b1, err := l.AppendIdempotent("k-single", [][]byte{[]byte("solo")})
584		if err != nil {
585			t.Fatal(err)
586		}
587		if _, err := l.Commit(b1); err != nil {
588			t.Fatal(err)
589		}
590		a, _ := l.Append([][]byte{[]byte("anon")})
591		g, err := l.AppendIdempotent("k-group", [][]byte{[]byte("grp")})
592		if err != nil {
593			t.Fatal(err)
594		}
595		if _, err := l.CommitGroup([]log.Batch{a, g}); err != nil {
596			t.Fatal(err)
597		}
598		l.Close()
599		return dir
600	}
601	
602	func assertKeyedState(t *testing.T, l *log.Log) {
603		t.Helper()
604		want := map[uint64]struct {
605			id  string
606			rec []byte
607		}{
608			1: {"k-single", []byte("solo")},
609			2: {"", []byte("anon")},
610			3: {"k-group", []byte("grp")},
611		}
612		for seq, w := range want {
613			got, err := l.Read(seq)
614			if err != nil || string(got[0]) != string(w.rec) {
615				t.Fatalf("Read(%d) = %q, %v; want %q", seq, got, err, w.rec)
616			}
617		}
618		var ids []string
619		if err := l.Scan(1, func(b log.Batch) error { ids = append(ids, b.ID()); return nil }); err != nil {
620			t.Fatalf("Scan: %v", err)
621		}
622		if !reflect.DeepEqual(ids, []string{"k-single", "", "k-group"}) {
623			t.Fatalf("scan ids = %v", ids)
624		}
625		for key, seq := range map[string]uint64{"k-single": 1, "k-group": 3} {
626			b, err := l.AppendIdempotent(key, [][]byte{wantRec(seq)})
627			if err != nil {
628				t.Fatalf("dedup %q after rebuild: %v", key, err)
629			}
630			if b.Seq() != seq {
631				t.Fatalf("dedup %q seq = %d, want %d", key, b.Seq(), seq)
632			}
633		}
634	}
635	
636	func wantRec(seq uint64) []byte {
637		if seq == 1 {
638			return []byte("solo")
639		}
640		return []byte("grp")
641	}
642	
643	func TestKeyedSidecarDefectsRebuildKeys(t *testing.T) {
644		mutate := func(t *testing.T, fn func([]byte) []byte) {
645			t.Helper()
646			dir := seedKeyedLog(t)
647			path := indexPath(dir)
648			data, err := os.ReadFile(path)
649			if err != nil {
650				t.Fatal(err)
651			}
652			out := fn(data)
653			if out == nil {
654				if err := os.Remove(path); err != nil {
655					t.Fatal(err)
656				}
657			} else if err := os.WriteFile(path, out, 0o644); err != nil {
658				t.Fatal(err)
659			}
660			l, err := log.Open(dir, log.Options{SegmentBytes: 1 << 20, Sync: true})
661			if err != nil {
662				t.Fatalf("Open with defective sidecar: %v", err)
663			}
664			defer l.Close()
665			assertKeyedState(t, l)
666		}
667	
668		t.Run("missing", func(t *testing.T) { mutate(t, func([]byte) []byte { return nil }) })
669		t.Run("garbage", func(t *testing.T) { mutate(t, func([]byte) []byte { return []byte("not an index at all") }) })
670		t.Run("wrong version", func(t *testing.T) {
671			mutate(t, func(d []byte) []byte { d[6] ^= 0xff; d[7] ^= 0xff; return d })
672		})
673		t.Run("bad checksum", func(t *testing.T) {
674			mutate(t, func(d []byte) []byte { d[len(d)-1] ^= 0xff; return d })
675		})
676		t.Run("truncated", func(t *testing.T) {
677			mutate(t, func(d []byte) []byte { return d[:len(d)-3] })
678		})
679	}
680	
681	// TestKeyedSidecarContradictionRebuildsKeys verifies the "index ahead
682	// of segments" contradiction: truncating the last segment makes adopt
683	// reject the sidecar and rebuild from reality, without losing earlier
684	// keyed batches' keys.
685	func TestKeyedSidecarContradictionRebuildsKeys(t *testing.T) {
686		dir := seedKeyedLog(t)
687		small := log.Options{SegmentBytes: 32, Sync: true}
688		// seedKeyedLog used 1MiB segments; reopen with tiny capacity so a new
689		// keyed commit rolls to its own segment, then drop that segment.
690		l := open(t, dir, small)
691		b, err := l.AppendIdempotent("k-late", [][]byte{[]byte("late")})
692		if err != nil {
693			t.Fatal(err)
694		}
695		if _, err := l.Commit(b); err != nil {
696			t.Fatal(err)
697		}
698		l.Close()
699	
700		files, _ := filepath.Glob(filepath.Join(dir, "*.seg"))
701		sort.Strings(files)
702		if err := os.Truncate(files[len(files)-1], 0); err != nil {
703			t.Fatal(err)
704		}
705		l2, err := log.Open(dir, small)
706		if err != nil {
707			t.Fatalf("Open: %v", err)
708		}
709		defer l2.Close()
710		// The indexed-but-missing late batch is gone; earlier keys survive.
711		if _, err := l2.Read(4); !errors.Is(err, log.ErrUnknownBatch) {
712			t.Fatalf("Read(4) err = %v, want ErrUnknownBatch", err)
713		}
714		for key, seq := range map[string]uint64{"k-single": 1, "k-group": 3} {
715			bb, err := l2.AppendIdempotent(key, [][]byte{wantRec(seq)})
716			if err != nil {
717				t.Fatalf("dedup %q: %v", key, err)
718			}
719			if bb.Seq() != seq {
720				t.Fatalf("dedup %q = %d, want %d", key, bb.Seq(), seq)
721			}
722		}
723	}
