// completeTruncation finishes an interrupted DeleteThrough: every
// segment file whose number is at or before the marker's boundary that
// is still on disk is removed, and the returned list only contains
// surviving segments. A missing file means the crash removal had
// already reached it; a removal that fails aborts the open, leaving the
// directory readable but untouched in mixed state for a retry.
func (l *Log) completeTruncation(indices []int, m truncateMarker) ([]int, error) {
	kept := make([]int, 0, len(indices))
	for _, n := range indices {
		if n <= m.segBound {
			if err := os.Remove(l.segmentPath(n)); err != nil && !os.IsNotExist(err) {
				return nil, fmt.Errorf("%w: %v", ErrRetentionFailed, err)
			}
			continue
		}
		kept = append(kept, n)
	}
	return kept, nil
}

