func (l *Log) writeEntry(entry []byte) (int, error) {
	if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
		if err := l.file.Close(); err != nil {
			return 0, err
		}
