			t.Fatalf("Read(2) = %q, %v", got, err)
		}
	}

	l = open(t, dir, opts)
	check(t, l)
	l.Close()

	// Delete the rebuildable sidecar: historical sequences must still
	// read as ErrTruncated, never ErrUnknownBatch.
	if err := os.Remove(filepath.Join(dir, "index.idx")); err != nil {
		t.Fatal(err)
	}
	l = open(t, dir, opts)
	check(t, l)
