	if n, err := l.DeleteThrough(2); err != nil || n != 1 {
		t.Fatalf("DeleteThrough = %d, %v", n, err)
	}
	calls := 0
	if err := l.Scan(1, func(log.Batch) error { calls++; return nil }); err != nil {
		t.Fatalf("Scan: %v", err)
