l.gen = 0
l.nextSeq = 1
l.through = seq
if err := l.installSnapshot(p, retained); err != nil && firstErr == nil {
	firstErr = err
}
for s := range l.index {
	if g, ok := oldGenBySeq[s]; ok {
		ref := l.index[s]
		ref.gen = g
