	if err != nil {
		return 0, err
	}
	boundOf := make(map[int]uint64, len(l.segs))
	for i := range l.segs {
		s := &l.segs[i]
		bound := uint64(0)
		if s.hasCommits {
			bound = s.LastSeq
		}
		if s.hasHoles && s.maxHole > bound {
			bound = s.maxHole
		}
		boundOf[s.file] = bound
	}
