func TestCommitAfterReopenUpgradesHoleOnlySegment(t *testing.T) {
	// A torn first entry recovered to a hole marker leaves a segment
	// that holds a hole but no committed batch. Reopening and committing
	// into the same file must upgrade that one listing entry, never
	// create a duplicate, and the hole stays permanent.
	dir := t.TempDir()
	opts := Options{SegmentBytes: 1 << 20}
	l := openTruncLog(t, dir, 1<<20)
	commitOne(t, l, "one")
	l.Close()

	// Torn entry reserving seq 2 in the same (only) segment.
	files, _ := filepath.Glob(filepath.Join(dir, "*.seg"))
	data, err := os.ReadFile(files[0])
	if err != nil {
		t.Fatal(err)
	}
	var torn []byte
	torn = append(torn, 'B', 'C', 'L', '1')
	var tmp [8]byte
	binary.LittleEndian.PutUint64(tmp[:], 2)
	torn = append(torn, tmp[:]...)
	binary.LittleEndian.PutUint32(tmp[:4], 1)
	torn = append(torn, tmp[:4]...)
	binary.LittleEndian.PutUint32(tmp[:4], 100)
	torn = append(torn, tmp[:4]...)
	torn = append(torn, []byte("only-a-prefix")...)
	if err := os.WriteFile(files[0], append(data, torn...), 0o644); err != nil {
		t.Fatal(err)
	}

	l2, err := Open(dir, opts)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	defer l2.Close()
	// Before the new commit, no public segment advertises a committed
	// batch beyond seq 1; internally the file is a hole-bearing entry.
	if segs := l2.Segments(); len(segs) != 1 || segs[0].LastSeq != 1 {
		t.Fatalf("segments before commit = %+v, want one ending at 1", segs)
	}
	if _, err := l2.Read(2); !errors.Is(err, ErrNotCommitted) {
		t.Fatalf("hole 2: %v", err)
	}
	seq := commitOne(t, l2, "after-hole")
	if seq != 3 {
		t.Fatalf("seq = %d, want 3", seq)
	}
	// Exactly one segment listing entry covering 1 and 3, with 2 a hole.
	if segs := l2.Segments(); len(segs) != 1 || segs[0].FirstSeq != 1 || segs[0].LastSeq != 3 {
		t.Fatalf("segments after commit = %+v, want one [1,3]", segs)
	}
	if _, err := l2.Read(2); !errors.Is(err, ErrNotCommitted) {
		t.Fatalf("hole 2 after commit: %v", err)
	}
}

